// Animated crowd dial — fills from 0 to target score with counting number.
// Perf notes: caches getComputedStyle (was called every frame), pre-renders the
// static track to an offscreen canvas, and keeps the parent drop-shadow filter
// on a SIBLING glow div so the canvas itself isn't re-rasterized 60×/sec.
const AnimatedDial = React.memo(function AnimatedDial({ score, color }) {
  const textRef = React.useRef(null);
  const canvasRef = React.useRef(null);

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const cssSize = 60;
    const size = Math.round(cssSize * dpr);
    const center = size / 2;
    const radius = Math.round(26 * dpr);
    const lineWidth = Math.round(6 * dpr);
    canvas.width = size;
    canvas.height = size;

    const ctx = canvas.getContext('2d');

    // Cache the track color ONCE (was a getComputedStyle call per frame — expensive style recalc)
    const trackColor = getComputedStyle(document.documentElement).getPropertyValue('--border-default').trim() || '#334155';

    // Pre-render the static gray ring to an offscreen canvas — drawn once, blitted each frame.
    const trackCanvas = document.createElement('canvas');
    trackCanvas.width = size;
    trackCanvas.height = size;
    const tctx = trackCanvas.getContext('2d');
    tctx.beginPath();
    tctx.arc(center, center, radius, 0, Math.PI * 2);
    tctx.strokeStyle = trackColor;
    tctx.lineWidth = lineWidth;
    tctx.stroke();

    let raf;
    const start = performance.now();
    const ease = t => 1 - Math.pow(1 - t, 3);

    const draw = (val) => {
      ctx.clearRect(0, 0, size, size);
      ctx.drawImage(trackCanvas, 0, 0);
      if (val > 0) {
        ctx.beginPath();
        ctx.arc(center, center, radius, -Math.PI / 2, -Math.PI / 2 + (val / 100) * Math.PI * 2);
        ctx.strokeStyle = color;
        ctx.lineWidth = lineWidth;
        ctx.lineCap = 'round';
        ctx.stroke();
      }
    };

    const tick = now => {
      const t = Math.min((now - start) / 1200, 1);
      const val = ease(t) * score;
      draw(val);
      if (textRef.current) textRef.current.textContent = `${Math.round(val)}%`;
      if (t < 1) raf = requestAnimationFrame(tick);
    };

    draw(0);
    if (textRef.current) textRef.current.textContent = '0%';
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [score, color]);

  return (
    <div style={{ width: '60px', height: '60px', position: 'relative', flexShrink: 0 }}>
      {/* Glow lives on a SIBLING div — not on a parent of the canvas. Otherwise every
          canvas frame would force the browser to re-rasterize the drop-shadow. */}
      <div aria-hidden style={{ position: 'absolute', inset: 0, borderRadius: '50%', boxShadow: `0 4px 12px rgba(0,0,0,0.3), 0 0 8px ${color}30`, pointerEvents: 'none' }} />
      <canvas ref={canvasRef} style={{ width: '60px', height: '60px', position: 'absolute', top: 0, left: 0, transform: 'translateZ(0)' }} />
      <div style={{ position: 'absolute', inset: '6px', borderRadius: '24px', backgroundColor: 'var(--bg-card-solid)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <span ref={textRef} style={{ fontSize: 'var(--t-body)', fontWeight: '600', color, lineHeight: 1 }}>0%</span>
      </div>
    </div>
  );
});

// One-tap reality check under the crowd forecast: a report from someone at the
// venue becomes a dated training row (venue_feedback) AND calibrates the live
// score for everyone else. Self-contained state; remount per venue via key.
const CrowdRealityCheck = React.memo(function CrowdRealityCheck({ placeId, venueName, predicted, ownerAsserted }) {
  const [open, setOpen] = useState(false);
  const [sent, setSent] = useState(null); // 'verified' | 'unverified'
  const [busy, setBusy] = useState(false);
  const [failed, setFailed] = useState(false);
  if (!placeId) return null;
  if (sent) {
    // The forecast only learns from a report the server could verify (a
    // check-in by tag, or a plan with two people here). The old line promised
    // every report sharpened it, which was false for nearly all of them.
    return (
      <p style={{ fontSize: 'var(--t-meta)', color: 'var(--text-secondary)', margin: '0 0 8px', fontWeight: '500' }}>
        {sent === 'verified'
          ? 'Thanks. Real reports sharpen the forecast for everyone.'
          : 'Thanks. Reports from a night here with your flock go into the forecast; this one is noted.'}
      </p>
    );
  }
  if (!open) {
    return (
      <button className="hit44"
        onClick={() => setOpen(true)}
        style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', padding: '6px 12px', margin: '0 0 8px', borderRadius: '10px', border: '1.5px solid var(--border-default)', backgroundColor: 'var(--bg-card-solid)', color: 'var(--text-secondary)', fontSize: 'var(--t-meta)', fontWeight: '600', cursor: 'pointer' }}
      >
        {/* When the number on screen is the bar's own claim, the check is the
            counterweight: reports from people in the room outrank the owner
            once three agree, and this button is where those reports come from. */}
        {ownerAsserted ? 'There now? Does this look right?' : 'There now? Rate the crowd'}
      </button>
    );
  }
  const opts = [
    // Same words the score ladder uses (crowdLabelFor). 'Packed' was a sixth
    // vocabulary item that appears nowhere else in the product.
    { level: 1, label: 'Quiet' },
    { level: 2, label: 'Moderate' },
    { level: 3, label: 'Very Busy' },
  ];
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap', margin: '0 0 8px', animation: 'fadeSlideIn 0.25s ease-out' }}>
      <span style={{ fontSize: 'var(--t-meta)', fontWeight: '500', color: 'var(--text-secondary)' }}>
        How busy is it actually:
      </span>
      {opts.map(o => (
        <button className="hit44"
          key={o.level}
          disabled={busy}
          onClick={async () => {
            setBusy(true);
            setFailed(false);
            try {
              const saved = await submitVenueFeedback({
                venue_place_id: placeId,
                venue_name: venueName,
                crowd_level: o.level,
                predicted_score: typeof predicted === 'number' ? Math.round(predicted) : null,
              });
              setSent(saved && saved.verified ? 'verified' : 'unverified');
            } catch (err) {
              console.error('[RealityCheck] submit failed:', err);
              // Was console-only: the buttons came back with no word.
              setFailed(true);
              setBusy(false);
            }
          }}
          style={{ padding: '4px 12px', borderRadius: '8px', border: '1.5px solid var(--border-default)', backgroundColor: 'var(--bg-card-solid)', color: 'var(--text-primary)', fontSize: 'var(--t-meta)', fontWeight: '600', cursor: busy ? 'wait' : 'pointer' }}
        >
          {o.label}
        </button>
      ))}
      {failed && (
        <span style={{ fontSize: 'var(--t-meta)', color: 'var(--accent-red-text)', fontWeight: '500' }}>That did not send. Try again.</span>
      )}
    </div>
  );
});

// =============================================================================
// Offline screen with a playable minigame. Reviewers open apps in Airplane
// Mode hunting for the webview white screen; Flock hands them a bird instead.
// Original art (Flock palette, code-drawn bird) — only the mechanics are
// borrowed from every runner game since the dinosaur. Auto-dismisses the
// moment connectivity returns.
// =============================================================================
/* The offline game's bird is the real mascot, not a canvas ellipse.
   Both frames are started HERE, at module scope, so they load while the app
   is still online. The offline screen only mounts once the network is gone,
   and by then a cold fetch would fail. drawBird falls back to the old vector
   bird if either image has not decoded, so the game is never birdless. */
const GAME_SPRITES = (() => {
  if (typeof Image === 'undefined') return { perch: null, flap: null };
  const load = (src) => { const img = new Image(); img.src = src; return img; };
  return { perch: load('/birdie/game-perch.png'), flap: load('/birdie/game-flap.png') };
})();
const spriteReady = (img) => !!img && img.complete && img.naturalWidth > 0;

const FlockBirdGame = () => {
  const canvasRef = React.useRef(null);
  const wrapRef = React.useRef(null);
  const [best, setBest] = useState(() => parseInt(localStorage.getItem('flockBirdBest') || '0', 10));

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    const W = 320, H = 400;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = W * dpr;
    canvas.height = H * dpr;
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    const rr = (x, y, w, h, r) => {
      // roundRect with fallback for older WebViews
      if (ctx.roundRect) { ctx.roundRect(x, y, w, h, r); return; }
      ctx.rect(x, y, w, h);
    };

    const CREAM = '#f1ede0', NAVY = '#16283d', NAVY_2 = '#1d3049', DIM = 'rgba(241,237,224,0.35)';
    const GROUND_H = 18, BIRD_X = 70;

    // ---- tuning (feel first: strong gravity, sharp flap, lagged tilt) ----
    const GRAVITY = 1380, FLAP = -395, PIPE_W = 56;
    const speedFor = (s) => Math.min(140 + s * 3.5, 205);   // ramps with score
    const gapFor = (s) => Math.max(152 - s * 1.2, 126);     // narrows with score

    let phase = 'ready'; // ready | play | dying | over
    let birdY = H / 2, vy = 0, tilt = 0, squash = 1;
    let pipes = [], score = 0, newBest = false;
    let groundX = 0, hitStopUntil = 0, flash = 0, shake = 0, diedAt = 0, scorePop = 1;
    let last = performance.now(), raf;

    // ---- mascot sprite ----
    // One scale for both frames so the bird does not change size mid-wingbeat.
    // The COLLISION box below is untouched (±10 x, ±7 y): this is an art swap,
    // and the game must not get harder or easier.
    const SPRITE_SCALE = 0.42;          // 96px flap frame -> ~40px on canvas
    const FLAP_FRAME_MS = 150;          // one wingbeat, not a flicker
    const MAX_DRAW_TILT = 0.44;         // ~25deg; a photo past this looks broken
    let flapFrameUntil = 0;

    // ---- backdrop: fixed stars + parallax skyline (0.35x speed) ----
    const stars = Array.from({ length: 24 }, (_, i) => ({
      x: (i * 97) % W, y: (i * 53) % (H - 160), r: (i % 3) * 0.4 + 0.5,
    }));
    const skyline = Array.from({ length: 12 }, (_, i) => ({
      x: i * 58, w: 34 + (i * 29) % 26, h: 34 + (i * 47) % 52,
    }));
    let skyX = 0;

    // ---- tiny synth (created on first user gesture; fails silently) ----
    let ac = null;
    const beep = (type, f0, f1, dur, vol) => {
      try {
        if (!ac) ac = new (window.AudioContext || window.webkitAudioContext)();
        const o = ac.createOscillator(), g = ac.createGain();
        o.type = type;
        o.frequency.setValueAtTime(f0, ac.currentTime);
        o.frequency.exponentialRampToValueAtTime(Math.max(f1, 1), ac.currentTime + dur);
        g.gain.setValueAtTime(vol, ac.currentTime);
        g.gain.exponentialRampToValueAtTime(0.0001, ac.currentTime + dur);
        o.connect(g).connect(ac.destination);
        o.start();
        o.stop(ac.currentTime + dur);
      } catch (_) { /* audio is garnish */ }
    };
    const sFlap = () => beep('square', 440, 620, 0.07, 0.05);
    const sScore = () => { beep('sine', 660, 660, 0.06, 0.06); setTimeout(() => beep('sine', 880, 880, 0.08, 0.06), 70); };
    const sHit = () => beep('sawtooth', 220, 60, 0.22, 0.09);

    const reset = () => { birdY = H / 2; vy = 0; tilt = 0; pipes = []; score = 0; newBest = false; };

    const flap = () => {
      const now = performance.now();
      if (phase === 'over') {
        if (now - diedAt > 500) { reset(); phase = 'ready'; }
        return;
      }
      if (phase === 'dying') return;
      if (phase === 'ready') phase = 'play';
      vy = FLAP;
      tilt = -0.38;      // snap nose-up on flap; gravity eases it back down
      squash = 0.82;     // quick squash, springs back
      flapFrameUntil = now + FLAP_FRAME_MS; // wings open for one beat
      sFlap();
    };

    const die = () => {
      phase = 'dying';
      hitStopUntil = performance.now() + 70;  // hit-stop: the world blinks
      flash = 0.55;
      shake = 9;
      sHit();
      const prevBest = parseInt(localStorage.getItem('flockBirdBest') || '0', 10);
      if (score > prevBest) {
        localStorage.setItem('flockBirdBest', String(score));
        setBest(score);
        newBest = true;
      }
    };

    // The original vector bird. Still the fallback for the first frame, and
    // for a cold offline start where neither PNG made it into the cache.
    const drawVectorBird = () => {
      ctx.scale(1 / squash, squash); // squash-and-stretch on flap
      ctx.fillStyle = CREAM;
      ctx.beginPath();
      ctx.ellipse(0, 0, 14, 11, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = NAVY;
      ctx.lineWidth = 2.5;
      ctx.lineCap = 'round';
      const w = vy < -60 ? -6 : 3; // wing up while rising
      ctx.beginPath();
      ctx.moveTo(-8, 0); ctx.quadraticCurveTo(-2, w, 5, 0);
      ctx.stroke();
      ctx.fillStyle = NAVY;
      ctx.beginPath(); ctx.arc(6, -3.5, 1.8, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.moveTo(13, -2); ctx.lineTo(19, 0); ctx.lineTo(13, 2); ctx.closePath(); ctx.fill();
    };

    const drawBird = (now) => {
      const wantFlap = now < flapFrameUntil;
      const img = wantFlap && spriteReady(GAME_SPRITES.flap)
        ? GAME_SPRITES.flap
        : (spriteReady(GAME_SPRITES.perch) ? GAME_SPRITES.perch : null);

      ctx.save();
      ctx.translate(BIRD_X, birdY);
      // Nose up while rising, nose down while falling, clamped so the photo
      // never reads as broken even in the death dive.
      ctx.rotate(Math.max(-MAX_DRAW_TILT, Math.min(MAX_DRAW_TILT, tilt)));

      if (!img) {
        drawVectorBird();
        ctx.restore();
        return;
      }

      // Half the squash of the vector bird: a photograph shows the stretch,
      // a flat shape hides it.
      const s = 1 + (squash - 1) * 0.5;
      ctx.scale(1 / s, s);
      const w = img.naturalWidth * SPRITE_SCALE;
      const h = img.naturalHeight * SPRITE_SCALE;
      // Both frames are tight crops, so they are placed by their centre.
      ctx.drawImage(img, -w / 2, -h / 2, w, h);
      ctx.restore();
    };

    const tick = (now) => {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;
      const frozen = now < hitStopUntil;
      const speed = speedFor(score);

      if (!frozen) {
        squash += (1 - squash) * Math.min(1, dt * 14);
        scorePop += (1 - scorePop) * Math.min(1, dt * 10);

        if (phase === 'play' || phase === 'dying') {
          vy += GRAVITY * dt;
          birdY += vy * dt;
          // tilt lags velocity: floats level, then noses into the dive
          const target = phase === 'dying' ? 1.5 : Math.max(-0.38, Math.min(1.1, vy / 520));
          tilt += (target - tilt) * Math.min(1, dt * (phase === 'dying' ? 6 : 9));
          if (birdY < 8) { birdY = 8; vy = Math.max(vy, 0); } // ceiling clamps, never kills
        }

        if (phase === 'play') {
          groundX = (groundX - speed * dt) % 24;
          skyX = (skyX - speed * 0.35 * dt) % (12 * 58);
          const spacing = 185 + speed * 0.25; // constant distance apart as speed ramps
          if (!pipes.length || pipes[pipes.length - 1].x < W - spacing) {
            const gap = gapFor(score);
            const gapY = 60 + Math.random() * (H - GROUND_H - 120 - gap);
            pipes.push({ x: W + PIPE_W, gapY, gap, passed: false });
          }
          for (const p of pipes) {
            p.x -= speed * dt;
            if (!p.passed && p.x + PIPE_W < BIRD_X - 14) { p.passed = true; score++; scorePop = 1.45; sScore(); }
            // forgiving hitbox: ~80% of the visual bird
            if (p.x < BIRD_X + 10 && p.x + PIPE_W > BIRD_X - 10) {
              if (birdY - 7 < p.gapY || birdY + 7 > p.gapY + p.gap) die();
            }
          }
          pipes = pipes.filter(p => p.x > -PIPE_W);
          if (birdY > H - GROUND_H - 10) die();
        } else if (phase === 'dying') {
          if (birdY > H - GROUND_H - 8) { birdY = H - GROUND_H - 8; phase = 'over'; diedAt = now; }
        } else if (phase === 'ready') {
          birdY = H / 2 + Math.sin(now / 300) * 7;
          tilt = Math.sin(now / 300 + 1) * 0.06;
          groundX = (groundX - 40 * dt) % 24;
        }
        shake = Math.max(0, shake - dt * 34);
        flash = Math.max(0, flash - dt * 2.2);
      }

      // ================= draw =================
      ctx.save();
      if (shake > 0.5) ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);

      ctx.fillStyle = NAVY;
      ctx.fillRect(-12, -12, W + 24, H + 24);
      ctx.fillStyle = DIM;
      for (const s of stars) { ctx.beginPath(); ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2); ctx.fill(); }
      // parallax skyline silhouette
      ctx.fillStyle = NAVY_2;
      for (const b of skyline) {
        const bx = ((b.x + skyX) % (12 * 58) + 12 * 58) % (12 * 58) - 58;
        ctx.fillRect(bx, H - GROUND_H - b.h, b.w, b.h);
      }
      // pipes
      ctx.fillStyle = CREAM;
      for (const p of pipes) {
        ctx.beginPath();
        rr(p.x, -8, PIPE_W, p.gapY + 8, [0, 0, 7, 7]);
        rr(p.x, p.gapY + p.gap, PIPE_W, H - p.gapY - p.gap - GROUND_H, [7, 7, 0, 0]);
        ctx.fill();
        // lip on each pipe mouth gives them dimension
        ctx.fillRect(p.x - 3, p.gapY - 9, PIPE_W + 6, 9);
        ctx.fillRect(p.x - 3, p.gapY + p.gap, PIPE_W + 6, 9);
      }
      // scrolling ground with motion notches
      ctx.fillStyle = CREAM;
      ctx.fillRect(-12, H - GROUND_H, W + 24, GROUND_H + 12);
      ctx.fillStyle = 'rgba(22,40,61,0.22)';
      for (let x = groundX - 24; x < W + 24; x += 24) {
        ctx.beginPath();
        ctx.moveTo(x, H - GROUND_H); ctx.lineTo(x + 12, H - GROUND_H);
        ctx.lineTo(x + 6, H - GROUND_H + 6); ctx.closePath(); ctx.fill();
      }
      drawBird(now);
      // score with pop
      if (phase !== 'ready') {
        ctx.save();
        ctx.translate(W / 2, 52);
        ctx.scale(scorePop, scorePop);
        ctx.fillStyle = CREAM;
        ctx.font = "600 34px 'Fraunces', Georgia, serif";
        ctx.textAlign = 'center';
        ctx.fillText(String(score), 0, 0);
        ctx.restore();
      }
      if (phase === 'ready') {
        ctx.fillStyle = CREAM;
        ctx.font = "600 15px 'Hanken Grotesk', sans-serif";
        ctx.textAlign = 'center';
        ctx.fillText('Tap to fly', W / 2, H / 2 + 74);
      } else if (phase === 'over') {
        ctx.textAlign = 'center';
        ctx.fillStyle = CREAM;
        ctx.font = "600 17px 'Hanken Grotesk', sans-serif";
        ctx.fillText(newBest ? 'New best!' : `${score} pillar${score === 1 ? '' : 's'}`, W / 2, H / 2 - 10);
        ctx.font = "500 13px 'Hanken Grotesk', sans-serif";
        ctx.fillStyle = DIM;
        ctx.fillText('Tap to go again', W / 2, H / 2 + 14);
      }
      // death flash
      if (flash > 0) {
        ctx.fillStyle = `rgba(241,237,224,${flash})`;
        ctx.fillRect(-12, -12, W + 24, H + 24);
      }
      ctx.restore();
      raf = requestAnimationFrame(tick);
    };

    const onKey = (e) => { if (e.code === 'Space') { e.preventDefault(); flap(); } };
    const wrap = wrapRef.current;
    wrap.addEventListener('pointerdown', flap);
    window.addEventListener('keydown', onKey);
    raf = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(raf);
      wrap.removeEventListener('pointerdown', flap);
      window.removeEventListener('keydown', onKey);
      try { if (ac) ac.close(); } catch (_) { /* already closed */ }
    };
  }, []);

  return (
    <div ref={wrapRef} style={{ touchAction: 'manipulation', cursor: 'pointer', userSelect: 'none', WebkitUserSelect: 'none' }}>
      <canvas ref={canvasRef} style={{ width: '320px', height: '400px', maxWidth: '86vw', borderRadius: '16px', display: 'block' }} />
      {best > 0 && (
        <p style={{ textAlign: 'center', fontSize: 'var(--t-meta)', color: 'rgba(241,237,224,0.5)', margin: '10px 0 0', fontWeight: '500' }}>Best: {best}</p>
      )}
    </div>
  );
};

const OfflineGate = () => {
  const [offline, setOffline] = useState(() => typeof navigator !== 'undefined' && !navigator.onLine);
  const [checking, setChecking] = useState(false);

  useEffect(() => {
    const goOnline = () => setOffline(false);
    const goOffline = () => setOffline(true);
    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);
    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  if (!offline) return null;

  const retry = async () => {
    setChecking(true);
    try {
      // Any HTTP response at all (even a 401) proves the network path works.
      //
      // The one raw fetch left in this file, and deliberately so. request()
      // in services/api.js is wrong for a connectivity PROBE in three ways:
      // it throws before sending whenever navigator.onLine is false, which is
      // exactly the state this button exists to disprove; it turns a 401 into
      // a thrown error, so the one response that best proves the network is
      // alive would read as "still offline"; and it attaches the stored token,
      // so a probe that happened to run on an expired session would trip the
      // session-expiry teardown and sign the user out of a tap on "Try again".
      await fetch(`${BASE_URL}/api/auth/me`, { cache: 'no-store' });
      setOffline(false);
    } catch (_) {
      // still offline — the game is right there
    } finally {
      setChecking(false);
    }
  };

  return (
    <div style={{ position: 'fixed', inset: 0, zIndex: 99999, backgroundColor: '#16283d', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '18px', padding: '24px', fontFamily: "'Hanken Grotesk', -apple-system, sans-serif" }}>
      <div style={{ textAlign: 'center' }}>
        <h1 style={{ fontFamily: 'var(--font-display, Georgia)', fontSize: 'var(--t-display)', fontWeight: '600', color: '#f1ede0', margin: '0 0 6px', letterSpacing: '-0.005em' }}>You're offline</h1>
        <p style={{ fontSize: 'var(--t-body)', color: 'rgba(241,237,224,0.55)', margin: 0 }}>Your plans are safe. Flock reconnects on its own.</p>
      </div>
      {/* The one thing this screen must never cover. The gate sits over the
          whole app whenever the browser says it is offline, which hid the SOS
          button and the sheet's own Call 911 from exactly the person in a
          dead zone who needs them. A phone call does not need the network. */}
      <a className="hit44" href="tel:911" style={{ display: 'inline-block', padding: '12px 28px', borderRadius: '12px', backgroundColor: '#c8372d', color: '#ffffff', fontSize: 'var(--t-body)', fontWeight: '600', textDecoration: 'none' }}>Call 911</a>
      <FlockBirdGame />
      <button className="hit44"
        onClick={retry}
        disabled={checking}
        style={{ padding: '12px 28px', borderRadius: '12px', border: 'none', backgroundColor: '#f1ede0', color: '#16283d', fontSize: 'var(--t-body)', fontWeight: '600', cursor: checking ? 'wait' : 'pointer', opacity: checking ? 0.7 : 1 }}
      >
        {checking ? 'Checking...' : 'Try again'}
      </button>
    </div>
  );
};

// The scroll-fade reveal component (IntersectionObserver) was deleted
// 2026-08-13. Four of its five usages wrapped the Nest feed with a staggered
// delay, so every return to the Nest tab replayed a fade and the flock list
// was briefly empty. Scroll-triggered reveals are on the absolute-ban list
// (SLOP-AUDIT A10 / H6). Content just is.

// ---------------------------------------------------------------------------
// EmptyMark — the photographed bird marks, for empty states only.
//
// These are the real mascots (cobalt Birdie and the cream one) mixed in with
// other birds, shot as transparent cutouts. They exist because short lists
// used to trail off into ~290px of blank canvas, which read as unfinished.
// Never put one on a state that already has content.
//
//   crowd  1024x498   the whole flock on a wire     transparent, any ground
//   steps   864x290   a few birds along a branch    transparent, any ground
//   money  1024x1024  birds sharing a banknote      CREAM GROUND, never navy
//
// -400 is the 1x and the full file is the 2x, the same pairing BirdieBird
// uses. object-fit: contain is load-bearing: the marks have very different
// aspect ratios (steps is nearly 3:1) and without it a width clamp at 390px
// would stretch them. Decorative, so alt="" + aria-hidden — the copy beside
// them carries the meaning.
//
// Both densities are served as WebP, with the PNGs kept as the <picture>
// fallback. The 2x entry was the expensive one and nothing was compressing it:
// mark-crowd.png is 1,194,700 bytes against 391,212 for the WebP, and
// mark-money.png 2,088,033 against 141,310. That weight is inside the Capacitor
// download, not just a slow request. The `-400` WebP files predate this and are
// also served by the marketing site, so they are used exactly as they are.
//
// LANDMINE for a new `name`: all FOUR files have to exist. <picture> falls back
// to the <img> when the browser cannot decode the source's TYPE, never when the
// chosen URL 404s, so a missing .webp is a broken image and not a silent
// downgrade to the PNG. crowd, steps and money each have all four today.
//
// display:contents on the <picture> keeps this component's layout identical to
// the bare <img> it replaced: the wrapper contributes no box, so the img is
// still the element the parent flex column lays out.
// ---------------------------------------------------------------------------
const EmptyMark = ({ name, height = 160, style }) => (
  <picture style={{ display: 'contents' }}>
    <source type="image/webp" srcSet={`/marks/mark-${name}-400.webp 1x, /marks/mark-${name}.webp 2x`} />
    <img
      src={`/marks/mark-${name}-400.png`}
      srcSet={`/marks/mark-${name}-400.png 1x, /marks/mark-${name}.png 2x`}
      alt=""
      aria-hidden="true"
      loading="lazy"
      draggable="false"
      style={{ display: 'block', height: `${height}px`, width: 'auto', maxWidth: '100%', objectFit: 'contain', ...style }}
    />
  </picture>
);

// ---------------------------------------------------------------------------
// FormGroup / FormRow: the shape a form screen is built out of.
//
// Written for the Create Flock rebuild (Jayden, TestFlight build 26: "don't
// just add the bird graphics, revamp the page so it follows SLOP-AUDIT"). That
// screen was one undifferentiated column of six controls stacked on the page
// background, which is the failure SLOP-AUDIT section S names: every row
// carries identical weight, so the eye has nowhere to rest and the user reads
// all of it to find one thing.
//
// The rules those two components encode, straight out of section S:
//
//   3. Groups are separated by the PAGE BACKGROUND, rows inside a group by
//      inset hairlines. Never one card per row, which is the rounded-bubble
//      tile grid A14 bans.
//   4. The group label sits OUTSIDE the container, small and grey. It is a
//      signpost, so giving it card chrome of its own doubles its weight for
//      nothing.
//
// Deliberately not a card grid, not an icon in a rounded square, and not a
// section that animates in. A hairline and a grey word do the whole job.
// ---------------------------------------------------------------------------
const FormGroup = ({ label, children, style }) => (
  <section style={{ marginBottom: '18px', ...style }}>
    {label && (
      <p style={{ fontSize: 'var(--t-micro)', fontWeight: '700', color: 'var(--text-tertiary)', margin: '0 0 6px 4px', textTransform: 'uppercase', letterSpacing: '0.6px' }}>{label}</p>
    )}
    <div style={{ backgroundColor: 'var(--bg-card-solid)', border: '1px solid var(--border-default)', borderRadius: '14px', boxShadow: 'var(--card-shadow-sm)' }}>
      {children}
    </div>
  </section>
);

const FormRow = ({ children, divided = false, style }) => (
  <div style={{ padding: '12px', borderTop: divided ? '1px solid var(--divider)' : 'none', ...style }}>{children}</div>
);

// A choice chip. One function for the day grid, the hour row and the budget
// context row, because they were three hand-rolled versions of the same
// control and two of them lit up GREEN with a coloured glow behind them on
// selection. Green is not in the palette (cream, navy, steel) and a glow is
// the ornament SLOP-AUDIT keeps cutting. Selected is a filled steel chip with
// white type: one channel of colour, one of weight, no shadow.
const ChoiceChip = ({ selected, onClick, children, style, ...rest }) => (
  <button
    type="button"
    className="hit44"
    aria-pressed={selected}
    onClick={onClick}
    style={{
      padding: '9px 14px',
      borderRadius: '10px',
      border: selected ? '1.5px solid transparent' : '1.5px solid var(--border-default)',
      backgroundColor: selected ? '#2d5a87' : 'var(--bg-card-solid)',
      color: selected ? '#ffffff' : 'var(--text-primary)',
      fontWeight: '600',
      fontSize: 'var(--t-label)',
      cursor: 'pointer',
      transition: 'background-color 0.15s ease, color 0.15s ease',
      ...style,
    }}
    {...rest}
  >
    {children}
  </button>
);

// ---------------------------------------------------------------------------
// The rotating greeting above "Hey, <name>" on the Nest tab.
//
// IT LIVES OUT HERE, AND THAT IS THE WHOLE POINT OF THE COMPONENT. The index
// and its 3-second timer used to be `useState` + `useEffect` inside
// FlockAppInner, which is the component that renders the entire application.
// Two things followed from that and neither was intended. The timer was
// created on mount with a stable dependency, so it ran for the whole session:
// every three seconds, on the chat screen, on Discover, on the venue
// dashboard, in the background of a flock somebody was mid-message in, it set
// state on the root and re-rendered the app to advance a twelve-pixel line of
// decoration that was not on screen. And even on the Nest tab, where the line
// IS on screen, the cheapest correct scope for that re-render is this element
// and not the other 584 KB of screen bodies FlockAppInner defines.
//
// As its own component the timer exists exactly as long as the greeting does:
// HomeScreen is only called for the home tab, so leaving the tab unmounts this
// and clears the interval. Nothing above it re-renders at all.
//
// The entries are functions, not strings, because the first one reads the
// clock: a phone left open across 5 PM must say "evening" on the next tick.
// `key={idx}` restarts the slot-machine animation on every change, which is
// what makes it read as a spin rather than a text swap.
const GREETINGS = [
  () => `Good ${new Date().getHours() < 12 ? 'morning' : new Date().getHours() < 17 ? 'afternoon' : 'evening'}`,
  () => 'What\'s the move?',
  () => 'Ready to flock up?',
  () => 'Let\'s make plans',
  () => 'Who\'s free tonight?',
  () => 'Time to link up',
  () => 'Rounding up the group...',
];

const CyclingGreeting = React.memo(function CyclingGreeting() {
  const [idx, setIdx] = useState(0);
  useEffect(() => {
    const iv = setInterval(() => setIdx((i) => (i + 1) % GREETINGS.length), 3000);
    return () => clearInterval(iv);
  }, []);
  return (
    <div style={{ height: '12px', overflow: 'hidden', position: 'relative' }}>
      <div key={idx} style={{ fontSize: 'var(--t-meta)', color: 'var(--text-tertiary)', margin: 0, letterSpacing: '0.3px', fontWeight: '500', lineHeight: 1, animation: 'slotSpin 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)' }}>{GREETINGS[idx]()}</div>
    </div>
  );
});

// The backend stores venue photo URLs as RELATIVE proxy paths
// (/api/venues/photo?ref=...) so senders can't smuggle tracking hosts.
// Resolve to the API origin whenever a stored value is rendered.
const resolveVenuePhoto = (u) => (u && u.startsWith('/api/') ? `${BASE_URL}${u}` : u || null);

// ---------------------------------------------------------------------------
// ONE FAILURE BEHAVIOUR FOR EVERY VENUE PHOTO IN THE APP.
// ---------------------------------------------------------------------------
// There were four of them, and three were wrong. `display = 'none'` on the
// Birdie card, the flock tile, the flock hero and the search list left the
// element hidden PERMANENTLY for that mount, with nothing in its place and (in
// two cases) the surrounding box collapsed to zero height, so a single dropped
// request quietly changed the layout under the reader. The venue detail hero
// painted a navy gradient over itself instead. Six other rows swapped in an
// inline SVG rectangle, which is a flat navy square rather than the placeholder
// the no-photo branch beside them would have drawn.
//
// A photo that failed to load is not a venue with no photo. It is a request to
// retry, and until then the same cream placeholder every other surface uses,
// so the card keeps its shape and reads as a venue rather than as a hole.
// Guarded against a placeholder that itself 404s, which would otherwise loop.
const VENUE_PHOTO_PLACEHOLDER = '/marks/venue-placeholder.jpg';
const onVenuePhotoError = (e) => {
  if (!e || !e.target || String(e.target.src || '').endsWith(VENUE_PHOTO_PLACEHOLDER)) return;
  e.target.onerror = null;
  e.target.src = VENUE_PHOTO_PLACEHOLDER;
};

// HTML-escape a user-derived string before it is interpolated into any raw
// HTML sink (e.g. MapLibre Popup.setHTML, which assigns innerHTML). This must
// be safe on its own — do NOT rely on upstream stripHtml on the write path.
// Escapes the five characters that can break out of text or an attribute.
const escapeHtml = (s) =>
  String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

// A link we did not write, before it becomes an href or a window.open.
//
// Four values in this file are third-party URLs that arrive over the API and go
// straight into a navigation sink: a venue's `website`, `menu_url` and
// `google_maps_url` (Google Places) and an event's `url` (Ticketmaster). None of
// them was checked. React strips a `javascript:` href with a warning, but
// `window.open('javascript:…')` is NOT React's to strip — it runs in this
// origin — and that is the sink the Tickets button uses.
//
// Nothing here is a claim that Google or Ticketmaster would send one. It is
// that "a URL from a vendor" and "a URL this app is willing to navigate to"
// have to be two different questions, so that the answer does not change the
// day a vendor field starts carrying something a venue owner typed. http(s)
// only; anything else answers null and the caller renders nothing rather than
// a link that goes somewhere else.
const httpUrl = (u) => (typeof u === 'string' && /^https?:\/\//i.test(u.trim()) ? u.trim() : null);

// The same link, opened without a handle back to this window.
//
// Every `<a target="_blank">` in this file already carries rel="noopener
// noreferrer". None of the `window.open` calls carried anything, and the two
// are not equivalent: browsers imply noopener for an ANCHOR with target=_blank
// and do NOT imply it for window.open, so the page that opens keeps a live
// `window.opener` pointing at Flock. One line of script on the far side
// (`opener.location = ...`) repaints the tab the user came from, and the tab
// they come back to is a sign-in screen they have no reason to distrust. The
// destinations here are a Ticketmaster event url and a wallet's web link,
// which is to say strings that arrive over the API from somebody else.
//
// httpUrl is the same gate the hrefs use, so a non-http(s) value opens nothing
// instead of opening a blank tab on the string "null". Deep links are NOT
// routed through here: a wallet scheme is not http(s), it has no window on the
// far side to hold an opener, and attemptPaymentHandoff's timing is measured
// against the bare call.
//
// Capacitor's iOS WebViewDelegationHandler answers createWebViewWith by
// handing the url to UIApplication.open and returning nil, ignoring
// WKWindowFeatures entirely, so the feature string changes nothing on the
// native shell.
const openExternal = (u) => {
  const url = httpUrl(u);
  if (!url || typeof window === 'undefined' || typeof window.open !== 'function') return false;
  window.open(url, '_blank', 'noopener,noreferrer');
  return true;
};

// Chat photos travel INSIDE the message body as a data: URL, on whichever
// transport is up. Socket.IO was raised to 8MB for exactly that; express.json()
// is still 1mb, so a photo over roughly 750KB sends fine on the socket and 413s
// the instant the REST fallback is used — the transport that only comes out
// when the network is already bad, which is the case the fallback exists for.
// Sizing the payload to fit BOTH is the client's half of that; the body limit
// wants raising too (reported, backend file).
//
// It also keeps the send honest about time: a 6MB base64 string is a slow
// upload with no progress bar behind it.
const CHAT_IMAGE_MAX_EDGE = 1600;
const CHAT_IMAGE_MAX_CHARS = 700 * 1024;
const CHAT_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
const dataUrlMime = (u) => (typeof u === 'string' ? ((/^data:([^;,]+)[;,]/.exec(u) || [])[1] || '') : '');

// The small twin prepareChatImage's output gets at SEND time. History pages
// used to ship the full ~700KB base64 of every photo, re-downloaded on every
// thread open, while the app draws at most 260px and has no zoom viewer; the
// server now stores this thumbnail alongside the full image and serves ONLY
// the thumbnail in history (routes/messages.js documents the whole rule,
// including why the server moderates the thumb separately). Never throws and
// never blocks a send: null just means the old bandwidth bill for this one
// photo. 360px covers the 260px box at retina density.
const CHAT_THUMB_MAX_EDGE = 360;
const CHAT_THUMB_MAX_CHARS = 88 * 1024;
const makeChatThumb = (dataUrl) => new Promise((resolve) => {
  try {
    if (typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image/')) { resolve(null); return; }
    const img = new Image();
    img.onload = () => {
      try {
        const longest = Math.max(img.naturalWidth, img.naturalHeight);
        if (!longest) { resolve(null); return; }
        const scale = Math.min(1, CHAT_THUMB_MAX_EDGE / longest);
        const canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
        canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
        const ctx = canvas.getContext('2d');
        if (!ctx) { resolve(null); return; }
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        let out = canvas.toDataURL('image/jpeg', 0.6);
        if (out.length > CHAT_THUMB_MAX_CHARS) out = canvas.toDataURL('image/jpeg', 0.45);
        resolve(out.length > CHAT_THUMB_MAX_CHARS ? null : out);
      } catch { resolve(null); }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  } catch { resolve(null); }
});

const prepareChatImage = (dataUrl) => new Promise((resolve) => {
  if (typeof dataUrl !== 'string' || !dataUrl.startsWith('data:image/')) {
    resolve({ error: "That photo couldn't be read. Try another one." });
    return;
  }
  const mime = dataUrlMime(dataUrl);
  // Already small enough and already a format the server accepts: leave it
  // alone. Re-encoding a photo that does not need it only costs quality.
  if (dataUrl.length <= CHAT_IMAGE_MAX_CHARS && CHAT_IMAGE_TYPES.includes(mime)) {
    resolve({ dataUrl });
    return;
  }
  // An animated GIF is refused server-side on purpose. Re-encoding one would
  // smuggle a still frame past that rule, so an oversized GIF is simply too
  // big to send.
  if (mime === 'image/gif') {
    resolve({ error: 'That GIF is too big to send. Try one under 1 MB.' });
    return;
  }
  const img = new Image();
  img.onload = () => {
    const longest = Math.max(img.naturalWidth, img.naturalHeight);
    if (!longest) {
      resolve({ error: "That photo couldn't be read. Try another one." });
      return;
    }
    const scale = Math.min(1, CHAT_IMAGE_MAX_EDGE / longest);
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      resolve({ error: "That photo couldn't be prepared. Try another one." });
      return;
    }
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    let out = canvas.toDataURL('image/jpeg', 0.82);
    for (let q = 0.65; out.length > CHAT_IMAGE_MAX_CHARS && q >= 0.4; q -= 0.15) {
      out = canvas.toDataURL('image/jpeg', q);
    }
    if (out.length > CHAT_IMAGE_MAX_CHARS) {
      resolve({ error: 'That photo is too big to send. Try a smaller one.' });
      return;
    }
    resolve({ dataUrl: out });
  };
  img.onerror = () => resolve({ error: "That photo couldn't be read. Try another one." });
  img.src = dataUrl;
});

// Does this optimistic bubble (or pending send) describe the row the server
// just echoed back? Text alone is not enough once a message can be an image
// with no text: every photo would match every other photo's empty body, and the
// wrong bubble would be reconciled while the right one hung there pending.
// `local` is either a rendered message (image on `image_url` in DMs, `image` in
// flock chat) or a stored send payload; `server` is the socket row.
//
// The server trims the text it stores, so the comparison trims both sides:
// sending "hi " matched nothing on the way back, and the bubble sat pending
// until it declared itself failed on a message that had saved fine.
const sameSend = (local, server) => {
  if (!local || !server) return false;
  const localImage = local.image_url || local.image || null;
  const trim = (v) => (typeof v === 'string' ? v.trim() : '');
  return trim(local.text) === trim(server.message_text)
    && (local.message_type || 'text') === (server.message_type || 'text')
    && localImage === (server.image_url || null);
};

// Message and DM primary keys are SERIAL, i.e. int4. Optimistic bubbles are
// minted with Date.now(), which is ~1.8e12 and therefore unmistakable: any id
// past this ceiling is a local placeholder, never a row the server issued.
// Without this test a not-yet-reconciled venue card looks like the newest
// message in the flock and survives every history read as a duplicate.
const SERVER_ID_MAX = 2147483647;
const isServerId = (id) => typeof id === 'number' && Number.isInteger(id) && id > 0 && id <= SERVER_ID_MAX;

// Fold a freshly fetched history into what is already on screen.
//
// A history fetch replaces the whole message list, and it cannot know about
// bubbles that legitimately belong there.
//
// 1. Sends the server never confirmed. Carry those forward — otherwise
//    stepping out of a chat and back in silently deletes a failed photo and
//    the retry attached to it — minus any the history now contains, which is
//    the case where the send actually landed while the client was giving up on
//    it. (This was `keepUnsettled`.)
// 2. Rows the SOCKET delivered after the server had already built the history
//    response. On screen entry that race is a few hundred milliseconds wide.
//    On the reconnect catch-up it is wide open, because live delivery resumes
//    the instant the room is re-entered while the HTTP read is still in
//    flight — so a catch-up meant to close a gap could open a new one. Only
//    rows strictly NEWER than everything the history returned are carried: ids
//    are serial, so "newer" is decidable. A local row missing from the middle
//    of the returned window was hidden by a moderator or deleted and must stay
//    gone; resurrecting it is the failure mode this avoids.
// 3. `keepOlder` — rows OLDER than the oldest the history returned. The route
//    answers with the newest 50, so a catch-up in a busy chat would otherwise
//    slice scrollback off the top of a conversation the user is reading. Those
//    rows are outside the window rather than absent from it, so the deletion
//    argument above does not apply. Screen entry does NOT ask for this: it is
//    the one moment a clean read of the server's truth is wanted, and the local
//    list there can be a stale session's.
// One shape for a stored row, wherever it was read from. Both message screens
// now have two readers each, the entry read and the older-page read behind
// "Load earlier messages", and two copies of a mapping are two chances for a
// field to be dropped on one path only. Kept at module scope so the older-page
// loaders and the history loaders cannot drift.
const mapDmRow = (m, myId) => ({
  id: m.id,
  sender: String(m.sender_id) === String(myId) ? 'You' : (m.sender_name || 'Unknown'),
  senderId: m.sender_id,
  text: m.message_text,
  time: new Date(m.created_at).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
  // Raw instant beside the formatted time: the day separators need a date,
  // and a formatted "9:41 PM" cannot say which night it belongs to.
  sentAt: m.created_at || null,
  message_type: m.message_type || 'text',
  venue_data: m.venue_data,
  image_url: m.image_url,
  thumb_url: m.thumb_url || null,
  reactions: m.reactions || [],
  reply_to: m.reply_to ? { id: m.reply_to.id, text: m.reply_to.message_text, sender: m.reply_to.sender_name } : null,
});

const mapFlockRow = (m, myId) => ({
  id: m.id,
  sender: String(m.sender_id) === String(myId) ? 'You' : (m.sender_name || 'Unknown'),
  senderId: m.sender_id,
  senderImage: m.sender_image || null,
  time: new Date(m.created_at).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }),
  sentAt: m.created_at || null,
  text: m.message_text,
  message_type: m.message_type || 'text',
  venue_data: m.venue_data || null,
  thumb: m.thumb_url || null,
  // Keep the whole reaction row, not just its emoji. The server hands each
  // reaction back as { emoji, user_id, user_name } and every consumer of a
  // flock reaction reads the user_id: groupReactions to decide whose pill is
  // whose, addReactionToMessage to know if a tap is a take-back, and the
  // socket add/remove handlers to dedupe by person. Stripping to a bare emoji
  // string on the reload path was the flock twin of the A1 DM bug: the pill
  // came back knowing a reaction existed but not that it was yours, so after a
  // reopen it could be seen and never taken back. mapDmRow keeps the row for
  // the same reason; the two mappers now agree.
  reactions: m.reactions || [],
  ...(m.image_url ? { image: m.image_url } : {}),
});

// Put an older page in front of what is on screen, dropping anything already
// there. The cursor is exclusive server-side, so an overlap can only come from
// a row that arrived between the two reads, which belongs where it already is.
const prependOlder = (current, older) => {
  const have = new Set((current || []).map(m => m.id));
  const fresh = (older || []).filter(m => !have.has(m.id));
  return fresh.length === 0 ? current : [...fresh, ...(current || [])];
};

// The oldest row on screen that the server actually gave us an id for. Pending
// and failed bubbles carry temp string ids and can never be a cursor.
const oldestServerId = (messages) => {
  let oldest = null;
  for (const m of messages || []) {
    if (!isServerId(m.id)) continue;
    if (oldest === null || m.id < oldest) oldest = m.id;
  }
  return oldest;
};

// What both message routes return when no `limit` is given. A page this size
// means there is probably more behind it; a shorter one is the top of the
// conversation. Change it here if the routes' default ever moves.
const DM_PAGE_SIZE = 50;

const mergeHistory = (local, history, { keepOlder = false } = {}) => {
  const hist = history || [];
  const mine = local || [];
  const settled = (m) => !m.pending && !m.failed;
  const unsettled = mine.filter((m) => (m.pending || m.failed) && !hist.some((h) => sameSend(m, {
    message_text: h.text,
    message_type: h.message_type,
    image_url: h.image_url || h.image || null,
  })));

  let oldestId = null;
  let newestId = null;
  for (const h of hist) {
    if (!isServerId(h.id)) continue;
    if (oldestId === null || h.id < oldestId) oldestId = h.id;
    if (newestId === null || h.id > newestId) newestId = h.id;
  }
  // An empty history says nothing about ordering, so nothing is positioned
  // against it.
  if (newestId === null) return [...hist, ...unsettled];

  const older = keepOlder ? mine.filter((m) => settled(m) && isServerId(m.id) && m.id < oldestId) : [];
  const newer = mine.filter((m) => settled(m) && isServerId(m.id) && m.id > newestId);
  return [...older, ...hist, ...newer, ...unsettled];
};

// A message somebody typed and watched fail is React state and nothing else, so
// a reload took it and the "Tap to retry" it was told to come back to with it.
// On a phone a reload is the ordinary case, not an unusual one: the tab
// refreshes, iOS evicts the web view, the person closes Flock and reopens it. So
// failed flock sends are mirrored to localStorage, per flock, and rehydrated
// when the chat's history loads. mergeHistory already hides a persisted failure
// that turns out to have landed (it matches a history row by content), and
// loadFlockMessages rewrites the store to drop it for good, so a send that
// finally arrived never comes back as a ghost failure.
const FAILED_MSG_KEY = 'flock_failed_msgs';
const readFailedStore = () => {
  try {
    const parsed = JSON.parse(localStorage.getItem(FAILED_MSG_KEY) || '{}');
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch { return {}; }
};
const writeFailedStore = (store) => {
  try { localStorage.setItem(FAILED_MSG_KEY, JSON.stringify(store)); } catch { /* quota or blocked storage: the failed bubble still lives in state this session */ }
};
const readFailedFlockMessages = (flockId) => {
  const list = readFailedStore()[String(flockId)];
  return Array.isArray(list) ? list : [];
};
const writeFailedFlockMessages = (flockId, list) => {
  const store = readFailedStore();
  if (list && list.length) store[String(flockId)] = list;
  else delete store[String(flockId)];
  writeFailedStore(store);
};
const persistFailedFlockMessage = (flockId, msg) => {
  const list = readFailedFlockMessages(flockId).filter((m) => m.id !== msg.id);
  list.push(msg);
  writeFailedFlockMessages(flockId, list);
};
const removeFailedFlockMessage = (flockId, id) => {
  writeFailedFlockMessages(flockId, readFailedFlockMessages(flockId).filter((m) => m.id !== id));
};

// How often the socket's liveness is sampled, and how close together two
// history reads of the SAME conversation are allowed to be. See the reconnect
// catch-up in App for why liveness is polled rather than subscribed to.
const SOCKET_SAMPLE_MS = 2000;
const CATCHUP_MIN_GAP_MS = 12000;

// One-line summary of a message for the places that can only show one line: the
// conversation list, the reply bar, a quoted reply.
//
// A photo message has NO text. It used to be sent with the literal word "Photo"
// as its body, which made every preview work by accident and put a word nobody
// typed into the database, into push notification bodies and into chat search
// results. The body is empty now and the WORD lives here, in the one layer that
// actually needs a label. Do not push it back down into the message.
//
// `hadContent` covers the conversation list loaded from GET /api/dm, which
// returns the stored body and nothing else: an empty body on a conversation that
// demonstrably has messages can only be an image-only message, so it reads as a
// photo rather than as "no messages".
const messagePreview = (m) => {
  if (!m) return '';
  const text = typeof m.text === 'string' ? m.text.trim() : '';
  if (text) return text;
  if (m.message_type === 'venue_card' || m.venue_data) return 'Venue';
  if (m.message_type === 'image' || m.image_url || m.image || m.hadContent) return 'Photo';
  return '';
};

// The one refusal the server gives for "no such account" and "not connected to
// you" alike (backend/utils/relationships.js NOT_CONNECTED_MESSAGE, deliberately
// one sentence so neither can be read off the other). It arrives as a 403 body
// over REST and on the socket's generic 'error' channel, and it is the answer to
// the most obvious thing a new user does: open New Message, search a name, and
// type. Matched on a phrase rather than the exact string so a wording change
// degrades to the old toast instead of to silence.
const NOT_CONNECTED_HINT = /connected with/i;

// The highest server id among messages somebody ELSE sent. Optimistic bubbles
// carry temp string ids and are excluded by isServerId, and your own messages
// are excluded because reading your own sending is not a thing to be told
// about. Returns null when there is nothing to compare, which is what "this
// chat's history has not been fetched" looks like and is deliberately NOT the
// same as zero: the caller has to be able to tell "nothing new" from "nothing
// known", and only the second one may not draw a dot.
const newestFromOthers = (messages) => {
  let newest = null;
  for (const m of messages || []) {
    if (!m || m.sender === 'You') continue;
    if (!isServerId(m.id)) continue;
    if (newest === null || m.id > newest) newest = m.id;
  }
  return newest;
};

// One clock for every conversation row. A DM row printed
// `toLocaleDateString(month, day)` unconditionally, so a message that landed a
// minute ago read "Aug 25" while the flock row beside it read "3:45 PM" for the
// same instant. Today gets the time, yesterday says so, and anything older gets
// the date, which is the only one of the three the old code ever showed.
const conversationStamp = (value) => {
  if (!value) return '';
  const then = new Date(value);
  if (Number.isNaN(then.getTime())) return '';
  const now = new Date();
  const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  if (then >= midnight) return then.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  const yesterday = new Date(midnight.getTime() - 24 * 60 * 60 * 1000);
  if (then >= yesterday) return 'Yesterday';
  return then.toLocaleDateString([], { month: 'short', day: 'numeric' });
};

// A guest's identity arrives in two forms and the roster used to keep only the
// wrong one. `id` is the namespaced string the roster is keyed on ("guest:12",
// deliberately non-numeric so it can never be mistaken for a user id); the REST
// roster also sends `guest_id`, the plain `guest_rsvps` row id. Reporting needs
// the number, because POST /api/reports validates content_id as an integer.
//
// Dropping it is why reporting a guest name was unreachable: the content type,
// the sheet's wording, the flock-membership visibility gate and migration 016
// (which widened the CHECK constraint so those reports stop 500ing) all shipped,
// and the client still had nothing to put in content_id.
//
// The socket event carries only the namespaced form, so parse that as the
// fallback rather than leaving a guest who just arrived unreportable until the
// next refetch.
const guestRsvpId = (g) => {
  const raw = g?.guest_id != null
    ? g.guest_id
    : String(g?.id ?? g?.guestId ?? '').replace(/^guest:/, '');
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 ? n : null;
};

// The server talks about votes as { venue_name, venue_id, voters, guest_count }
// where voters are either { id, name } rows (GET /votes) or plain names (vote
// POST + the new_vote socket event). The UI reads { venue, type, voters, ... }
// with the signed-in user shown as 'You'. Everything that lands in flock.votes
// goes through here so peer votes stop rendering as undefined venues.
const normalizeVotes = (raw, me, previous = []) => {
  if (!Array.isArray(raw)) return Array.isArray(previous) ? previous : [];
  const myId = me?.id != null ? String(me.id) : null;
  const myName = me?.name || null;
  return raw
    .map((v) => {
      const venue = v.venue || v.venue_name || '';
      const prior = (Array.isArray(previous) ? previous : []).find((p) => p.venue === venue);
      return {
        venue,
        type: v.type || prior?.type || 'Venue',
        place_id: v.place_id || v.venue_id || prior?.place_id || null,
        voters: (v.voters || []).map((p) => {
          if (typeof p === 'string') return myName && p === myName ? 'You' : p;
          if (!p || typeof p !== 'object') return '';
          if (myId != null && String(p.id) === myId) return 'You';
          return p.name || '';
        }).filter(Boolean),
        guestCount: Number(v.guest_count ?? v.guestCount ?? 0) || 0,
      };
    })
    .filter((v) => v.venue);
};

// Members who voted plus guest-link votes, which have no identities.
const voteTotal = (v) => (v?.voters?.length || 0) + (v?.guestCount || 0);

// Has the person reading this screen already voted in this flock?
//
// normalizeVotes above rewrites the caller's own name to the literal 'You' on
// every row it produces, and both vote surfaces already find the reader's pick
// that way. This asks the same question of a whole flock, so a card addressed
// to YOU can stop demanding something you have already done. `votes` is `[]`
// on a flock the app has not opened this session, which reads as "not voted"
// and is the honest answer: nothing on the client knows otherwise until the
// tallies are fetched.
const hasCastMyVote = (flock) => (flock?.votes || []).some(v => (v?.voters || []).includes('You'));

// "1 members" was on screen in three places. One label, counted once.
const memberCountLabel = (flock) => {
  const n = (Array.isArray(flock?.members) && flock.members.length) || flock?.memberCount || flock?.member_count || 0;
  return `${n} member${n === 1 ? '' : 's'}`;
};

/* ═══════════════════════════════════════════════════════════════════
   WHEN. The create screen and the flock "Details" panel both pick a day
   from a relative chip ("Tonight", "This Weekend") and an hour from a
   chip ("9 PM"). Neither of those is a timestamp, and for a long time
   neither of them was sent: every flock landed with event_time NULL,
   which is why they all read "TBD" and never reached the Plans calendar.

   These two helpers turn the pair into a real instant. new Date(y, m, d, h)
   builds the date in the browser's own timezone, so 9 PM means 9 PM where
   the user is standing; .toISOString() hands the API the UTC instant it
   stores (backend/routes/flocks.js validates event_time with isISO8601).
   ═══════════════════════════════════════════════════════════════════ */
const FLOCK_DAY_CHOICES = ['Tonight', 'Tomorrow', 'This Weekend', 'Next Week'];
const FLOCK_HOUR_CHOICES = ['7 PM', '8 PM', '9 PM', '10 PM', '11 PM'];

const parseHourChoice = (label) => {
  const m = /^\s*(\d{1,2})\s*(AM|PM)\s*$/i.exec(String(label || ''));
  if (!m) return 21;
  const h = parseInt(m[1], 10) % 12;
  return /pm/i.test(m[2]) ? h + 12 : h;
};

const resolveEventTime = (dayLabel, hourLabel, now = new Date()) => {
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate(), parseHourChoice(hourLabel), 0, 0, 0);
  switch (dayLabel) {
    case 'Tomorrow':
      d.setDate(d.getDate() + 1);
      break;
    case 'This Weekend': {
      const day = d.getDay(); // 0 Sun … 6 Sat
      if (day === 6 || day === 0) {
        // Already the weekend. Keep today unless that hour is behind us.
        if (d <= now) d.setDate(d.getDate() + (((6 - day + 7) % 7) || 7));
      } else {
        d.setDate(d.getDate() + ((6 - day + 7) % 7));
      }
      break;
    }
    case 'Next Week':
      d.setDate(d.getDate() + 7);
      break;
    case 'Tonight':
    default:
      // A "tonight" slot that has already gone by means tomorrow night.
      if (d <= now) d.setDate(d.getDate() + 1);
      break;
  }
  return d;
};

// One label for a flock's time, used by every surface that shows one.
const formatEventTime = (iso) => {
  if (!iso) return 'TBD';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return 'TBD';
  // Weekday alone is ambiguous past one week: a Next Week plan read "Wed
  // 9:00 PM" everywhere, identical to tonight's Wednesday. Six days keeps
  // this week bare and dates everything past it.
  if (d.getTime() - Date.now() > 6 * 24 * 3600 * 1000) {
    return d.toLocaleString([], { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
  }
  return d.toLocaleString([], { weekday: 'short', hour: 'numeric', minute: '2-digit' });
};

/* Momentum. The server scores a brand-new flock at 50/100 (it hands out a
   full 20 points for "no budget to collect" and 30 for the creator's own
   RSVP), so a plan with no venue, no time and one person read "Almost
   There". The score is still useful as a bar; the STAGE is re-derived here
   from the three facts a person would actually check. */
const MOMENTUM_STAGES = [
  { key: 'idea', label: 'Idea', color: '#94a3b8' },
  { key: 'building', label: 'Building', color: '#f59e0b' },
  { key: 'almost_there', label: 'Almost There', color: '#F59E0B' },
  // 'Ready', not 'Locked In': Locked In is the STATUS word for a confirmed
  // flock, and this stage fires on signals alone, so the old label sat next
  // to a "Planning" chip claiming the opposite. The stage means "everything
  // is in place", and only the status may say locked.
  { key: 'locked_in', label: 'Ready', color: '#22c55e' },
  { key: 'lets_go', label: "Let's Go", color: '#4a7ba7' },
];

const momentumStageKey = (m) => {
  if (!m) return 'idea';
  const hasPeople = (m.accepted || 0) >= 2;
  const signals = [!!m.hasVenue, !!m.hasTime, hasPeople].filter(Boolean).length;
  if (signals === 3) return (m.score || 0) >= 85 ? 'lets_go' : 'locked_in';
  if (signals === 2) return 'almost_there';
  if (signals === 1) return 'building';
  return 'idea';
};

/* ── LIST SKELETON ───────────────────────────────────────────────────────
   Three cards in the shape of the rows they stand in for. Every list that
   fetches on mount uses this, because the alternative is what the app used to
   do: render the empty state during the fetch, so a returning user with six
   flocks was told "No flocks yet" for as long as the network took. Empty
   states are a claim about the user's data and must not be made before the
   data arrives. (SLOP-AUDIT.md rule 10: skeletons for feeds and pages.) */
const ListSkeleton = ({ count = 3, thumb = 46, thumbRadius = 14, label = 'Loading' }) => (
  <div role="status" aria-label={label}>
    {Array.from({ length: count }, (_, i) => (
      <div key={i} style={{ display: 'flex', gap: '12px', padding: '12px', marginBottom: '10px', borderRadius: '14px', border: '1px solid var(--border-subtle)', backgroundColor: 'var(--bg-card-solid)' }}>
        <div className="skeleton" style={{ width: `${thumb}px`, height: `${thumb}px`, borderRadius: `${thumbRadius}px`, flexShrink: 0 }} />
        <div style={{ flex: 1, minWidth: 0, paddingTop: '4px' }}>
          <div className="skeleton" style={{ width: '60%', height: '14px', borderRadius: '4px', marginBottom: '8px' }} />
          <div className="skeleton" style={{ width: '40%', height: '11px', borderRadius: '4px', marginBottom: '10px' }} />
          <div className="skeleton" style={{ width: '80%', height: '10px', borderRadius: '4px' }} />
        </div>
      </div>
    ))}
  </div>
);

/* ── CHAT SKELETON ───────────────────────────────────────────────────────
   The same argument as ListSkeleton, one screen further in. Opening a DM used
   to render "Say hi to start the conversation!" while the history was still on
   the wire, so every first open of a thread with months of messages in it
   opened on a sentence saying there were none. The flock chat had the milder
   version of the same thing: its empty state is correctly gated on
   `messagesLoading`, which left the message area completely blank instead.
   Bubbles in the shape of bubbles, alternating sides. */
const ChatSkeleton = ({ label = 'Loading messages' }) => (
  <div role="status" aria-label={label} style={{ padding: '4px 0' }}>
    {[
      { mine: false, w: '62%' },
      { mine: true, w: '48%' },
      { mine: false, w: '72%' },
      { mine: true, w: '38%' },
    ].map((row, i) => (
      <div key={i} style={{ display: 'flex', gap: '10px', marginBottom: '14px', flexDirection: row.mine ? 'row-reverse' : 'row' }}>
        <div className="skeleton" style={{ width: '32px', height: '32px', borderRadius: '16px', flexShrink: 0 }} />
        <div className="skeleton" style={{ width: row.w, height: '38px', borderRadius: '16px' }} />
      </div>
    ))}
  </div>
);

/* ── FLOCK TILE ──────────────────────────────────────────────────────────
   The 46px square next to a flock in the Messages list. It used to be one of
   five stock JPEGs (public/group-avatars/flock-1..5.jpg) picked by hashing the
   flock id, so a real group called "Sarah's birthday" was illustrated with a
   dog in sunglasses. That is fabricated decoration standing in for user
   content, so the files are gone and the tile is now the flock's own initial
   on one of four brand swatches, keyed off the flock id so a given flock keeps
   the same colour forever. A flock that has picked a venue shows the venue
   photo instead — that one IS the flock's own content. */
const FLOCK_TILE_SWATCHES = [
  { bg: '#1e293b', fg: '#f1ede0' }, // navy
  { bg: '#2d5a87', fg: '#f1ede0' }, // steel
  { bg: '#e8e0d5', fg: '#1e293b' }, // cream
  { bg: '#c8b696', fg: '#1e293b' }, // sand
];

const flockTileSwatch = (flockId) => {
  const seed = String(flockId || '');
  let hash = 0;
  for (let i = 0; i < seed.length; i++) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  return FLOCK_TILE_SWATCHES[hash % FLOCK_TILE_SWATCHES.length];
};

const flockTileInitial = (name) => {
  const ch = String(name || '').trim().charAt(0);
  return ch ? ch.toUpperCase() : '?';
};

// ═══════════════════════════════════════════════════════════════════════════
// ONE crowd vocabulary for the whole app.
//
// backend/services/crowdEngine.js getLabel() owns these five bands and these
// cut points. This file used to carry FIVE different local ladders, most of
// them three bands, so the same score of 65 read "Moderate" in the venue
// sheet, "Busy" in the search row and "Very Busy" in the alternatives list,
// while the website called it "Busy". Same story for the colour: a 65 was red
// on the site and amber in the app because the app's threshold was 70.
//
// Never inline another ladder. Call these.
// ═══════════════════════════════════════════════════════════════════════════
// A crowd reading is only 'live' for so long. Shared by the LIVE/ESTIMATED
// chip and by the back-navigation snapshot check so they never disagree about
// what counts as current.
const CROWD_FRESH_MS = 5 * 60 * 1000;
// Re-cut 2026-08-28 with the qmap arming; the reasoning lives on the
// canonical copy in backend/services/crowdEngine.js getLabel, which this
// mirrors word for word and cut for cut.
const crowdLabelFor = (score) => {
  if (!Number.isFinite(score)) return null;
  if (score <= 20) return 'Quiet';
  if (score <= 39) return 'Not Busy';
  if (score <= 69) return 'Steady';
  if (score <= 84) return 'Busy';
  return 'Packed';
};
// THE MEASURED HOUR-ORDERING FLOOR, mirrored from
// backend/services/crowdEngine.js HOUR_ORDERING_MIN_GAP.
//
// Two hours closer together than this cannot be ordered by anything Flock
// has: on within-night hour pairs the model orders 62.7% right and the
// popular-times curve alone orders the same pairs 63.1% right, and inside ten
// points it is a coin flip (backend/scripts/ml/HOUR-RANKING-EVAL.md). Every
// server-side "which hour is better" decision refuses below this number, so
// any client that draws its own comparison has to refuse at the same one, or
// the card publishes a direction the sentence beside it declines to publish.
//
// This is an ORDERING floor and it is not interchangeable with the model's
// level error: the level MAE is a statement about how far one number sits
// from the truth, which licenses nothing about whether one hour outranks
// another. __tests__/hourOrderingFloor.test.js pins this to the server's
// constant so the two cannot drift.
const HOUR_ORDERING_MIN_GAP = 10;

// Red at 85+ since 2026-08-28, matching the re-cut ladder: under the
// calibrated venue-relative scale, Busy (70-84) is a normal good evening and
// wears amber; only Packed alarms. One place owns the thresholds, so a
// surface that wants a different WEIGHT of the same reading cannot drift off
// the boundaries every other surface is drawing against.
const crowdBandFor = (score) => {
  if (!Number.isFinite(score)) return null;
  if (score > 84) return 'red';
  if (score > 39) return 'amber';
  return 'green';
};

// The standard weight. `c` is the theme palette when a caller has it.
const crowdColorFor = (score, c) => {
  const band = crowdBandFor(score);
  if (!band) return null;
  if (band === 'red') return (c && c.red) || '#EF4444';
  if (band === 'amber') return (c && c.amber) || '#F59E0B';
  return '#22C55E';
};

// The ink twin. Same three bands, but in the text-safe tokens: the saturated
// hues above are for dots and bars, and painted as TEXT on the app's light
// surfaces they measure 1.8 to 3.8 to 1 (the same accent-as-text failure the
// accessibility sweep fixed for the palette literals, reintroduced through
// this computed hue). Words and percentages take these; the swatch beside
// them keeps the hue.
const crowdInkFor = (score, c) => {
  const band = crowdBandFor(score);
  if (!band) return null;
  if (band === 'red') return (c && c.redText) || 'var(--accent-red-text)';
  if (band === 'amber') return (c && c.amberText) || 'var(--accent-amber-text)';
  return 'var(--accent-green-text)';
};

// Reduced motion, honored on the one animation CSS cannot reach: MapLibre's
// camera. The global stylesheet collapses every CSS animation when the user
// asks for stillness, but flyTo is a JS tween. jumpTo lands the same place
// with no flight.
const mapEase = (map, opts) => {
  const still = typeof window !== 'undefined' && window.matchMedia
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (still) map.jumpTo({ center: opts.center, zoom: opts.zoom });
  else map.flyTo(opts);
};

// The heavy weight, for a surface that fills a large area with the colour
// rather than tinting a dot or a word with it. The crowd scale above has
// exactly one shade per band, and a card-width block of #EF4444 reads as an
// alarm rather than a measurement, so the deep end comes from the accent
// tokens the app already uses to write the same three readings in text
// (`--accent-red-text` on "Projected busier than you tonight" is the same
// number in the same colour, two cards down). No new hex, and both themes are
// already resolved: the dark palette lightens these on purpose, because on a
// dark card the deep end of a hue is the unreadable one.
const crowdColorDeepFor = (score) => {
  const band = crowdBandFor(score);
  if (!band) return null;
  if (band === 'red') return 'var(--accent-red-text)';
  if (band === 'amber') return 'var(--accent-amber-text)';
  return 'var(--accent-green-text)';
};

// Week Ahead's bar well. A score of 100 draws 55px at the chart's scale, so
// 60 is the smallest number that no projection can overflow. It is the height
// the row used to declare for the whole column, which is why the labels had
// nowhere to go; here it bounds the BAR only and the labels sit under it.
const WEEK_BAR_WELL_PX = 60;

// The faint end of the week's ramp. Every bar is drawn in the deep colour, so
// this floor is what keeps the quietest evening dark rather than washed pink;
// the busiest still draws at 1, so a week with spread still shows its spread.
const WEEK_BAR_WEIGHT_MIN = 0.72;

// "Today, Hour by Hour" has the same well, for the same reason the week chart
// grew one. That row used to declare `height: 50px` around columns of bar plus
// hour label that measure 66px at 375px, so every labelled column hung 16px out
// of the top of its own row and the two tallest landed inside the box of the
// heading above them. A score of 100 draws 50px at this chart's scale, so 50 is
// the smallest well no hour can overflow. The row itself declares no height:
// it is as tall as the well plus the labels that sit under it, in flow.
const HOUR_BAR_WELL_PX = 50;

// ═══════════════════════════════════════════════════════════════════════════
// BIRDIE'S CONTEXT WINDOW
//
// backend/routes/ai.js accepts at most AI_CHAT_MAX_MESSAGES messages and at
// most AI_CHAT_MAX_MESSAGE_CHARS characters in each of them, and answers 400
// (`CONVERSATION_TOO_LONG`, and "Message too long") past either. This client
// used to send the whole conversation untruncated, so the 25th turn of every
// Birdie chat was refused: the chat simply stopped answering at the point it
// had got interesting.
//
// NEITHER NUMBER MAY BE RAISED HERE. backend/server.js sizes that route's
// scoped JSON body parser directly from them (24 * 4000 * 4, ~449KB), so a
// client that sends more converts an honest, actionable 400 into a 413 that
// body-parser generates before any route code runs, and a 413 can carry no
// code, no message and nothing to act on. The server owning the cap is the
// point; this half only has to stay inside it.
const AI_CHAT_MAX_MESSAGES = 24;
const AI_CHAT_MAX_MESSAGE_CHARS = 4000;

// The last `max` turns. The SAME array comes back when nothing had to go, so
// the ordinary short conversation allocates nothing.
const trimAiHistory = (messages, max = AI_CHAT_MAX_MESSAGES) => {
  if (!Array.isArray(messages)) return [];
  const limit = Number.isInteger(max) && max > 0 ? max : AI_CHAT_MAX_MESSAGES;
  return messages.length > limit ? messages.slice(-limit) : messages;
};

// Where Birdie's memory starts, as an index into the transcript on screen: the
// oldest message that will still be in the window after the visitor sends one
// more. 0 means the whole conversation fits and nothing is marked, which is
// every conversation until the 24th message.
const aiMemoryCutIndex = (count, max = AI_CHAT_MAX_MESSAGES) => {
  const limit = Number.isInteger(max) && max > 0 ? max : AI_CHAT_MAX_MESSAGES;
  if (!Number.isInteger(count) || count < limit) return 0;
  return count - (limit - 1);
};

// What actually goes on the wire: {role, text}. The venue names Birdie showed
// are folded into its own turns so it remembers what it recommended.
//
// The per-message clamp is not tidiness. `messages.*.text` is capped on EVERY
// element, history included, so one over-long message in a thread used to 400
// every later send in that same thread, permanently, with no way out of it.
// Bubbles flagged `error` are the app talking (a refusal, a dead network).
// They used to go back to the model as its own words, so the next turn was
// told it had previously said "Couldn't reach Flock".
const toAiWireMessages = (messages) => (Array.isArray(messages) ? messages : []).filter((m) => !m?.error).map((m) => {
  let text = typeof m?.text === 'string' ? m.text : '';
  if (m?.role === 'assistant' && Array.isArray(m.venues) && m.venues.length > 0) {
    text += '\n[Venues shown: ' + m.venues.map(v => `${v.name} (${v.crowd_label || 'crowd unknown'}, ${v.is_open ? 'open' : 'closed'})`).join(', ') + ']';
  }
  return {
    role: m?.role,
    text: text.length > AI_CHAT_MAX_MESSAGE_CHARS ? text.slice(0, AI_CHAT_MAX_MESSAGE_CHARS) : text,
  };
});

// ---------------------------------------------------------------------------
// Paying somebody back, when the wallet app may not be installed
//
// GET /api/billing/:flockId/payment-links (backend/routes/billing.js) returns a
// `methods` array, and the three shapes it builds are NOT interchangeable:
//
//   venmo    deepLink venmo scheme + webLink venmo.com
//   cashapp  deepLink cashapp scheme + webLink cash.app
//   zelle    deepLink null, webLink null, `instructions` prose, on purpose,
//            because Zelle lives inside each bank's own app and has no shared
//            scheme to open
//
// The Pay control used to test the deep link and open it straight away, with
// the web link reached only when the deep link was NULL. On iOS that is a
// control that
// cannot succeed for anybody without the wallet app installed: window.open on a
// non-http URL reaches Capacitor's WebViewDelegationHandler, which calls
// UIApplication.open(url), and -open: on a scheme no installed app claims fails
// SILENTLY. No error, no exception, no callback, no rejected promise. The payer
// taps "Pay", nothing happens, and the money conversation goes back to the group
// chat.
//
// Nothing available in this app can ask the question directly. -canOpenURL: is
// the API that answers it (and Info.plist's LSApplicationQueriesSchemes is the
// list that authorises it), but no installed plugin exposes it to JavaScript:
// @capacitor/app 8.x has getInfo, getState, getLaunchUrl, exitApp, minimizeApp
// and the listeners, and no canOpenUrl. So the only signal is whether the app
// went away, which is what the two helpers below race against a timeout.
// ---------------------------------------------------------------------------

// How long the app has to disappear before we conclude the wallet app never
// opened. An installed app takes the foreground in well under a second; this is
// generous enough for a cold launch on a tired phone and short enough that a
// payer who got nothing is not left staring at a dead screen.
const PAYMENT_HANDOFF_MS = 1500;

// One `methods` element reduced to what the UI can actually do with it.
const paymentRoutes = (method) => {
  const str = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
  const appUrl = str(method?.deepLink);
  const webUrl = str(method?.webLink);
  const instructions = str(method?.instructions);
  return {
    appUrl,
    webUrl,
    instructions,
    // A row with none of the three has nothing to do when it is tapped, so it
    // is never rendered as a control. The route does not build one today; a
    // payer whose handle is only stored on one of the three services gets one
    // method, not three empty ones.
    actionable: !!(appUrl || webUrl || instructions),
  };
};

// "venmo.com", for the button that offers the web route by name. Anything that
// is not a parseable absolute URL has no name to show and gets none.
const paymentWebHost = (webUrl) => {
  if (typeof webUrl !== 'string' || !webUrl) return null;
  try {
    const host = new URL(webUrl).host.replace(/^www\./, '');
    return host || null;
  } catch (err) {
    return null;
  }
};

/**
 * Hand off to a wallet app, and notice when the handoff did not happen.
 *
 * The race, and why the fallback cannot fire on a handoff that WORKED:
 *
 *   - The deep link is opened inside the tap, so it is a real user gesture.
 *   - If the wallet app takes the foreground, WKWebView backgrounds. That fires
 *     `visibilitychange` with visibilityState 'hidden' and `pagehide`. Either
 *     one cancels the timer, and both are edges that only happen when something
 *     else is on screen.
 *   - The timeout re-reads document.visibilityState before it does anything, so
 *     a listener that never ran (a missed event, a suspended timer that fires
 *     late on resume) still cannot produce a false "it did not open": a hidden
 *     document is the app not being on screen, whatever the events did.
 *   - `blur` is deliberately NOT one of the signals. In WKWebView the window
 *     blurs when a native input takes focus and when the keyboard opens, with
 *     the app still fully on screen, and treating that as a handoff would
 *     recreate exactly the silent failure this exists to fix.
 *
 * Where the race is weakest, stated plainly: a DESKTOP browser answers
 * window.open on an unknown scheme by opening a real blank tab, and that tab
 * taking focus hides the opener, which reads here as a successful handoff and
 * suppresses the prompt. That is the iOS shell's signal being borrowed by a
 * platform it was not measured on. It is not a regression (the desktop tap
 * previously did nothing AND offered no web route), and bill splitting is a
 * phone flow, but it is the case to fix first if this ever needs to work on a
 * laptop.
 *
 * The other direction matters too: the fallback is a PROMPT, not a navigation.
 * Auto-opening the web link on the timeout would not work here and would be a
 * second control that cannot succeed. WKWebView blocks window.open outside a
 * user gesture unless javaScriptCanOpenWindowsAutomatically is set, and
 * Capacitor's CAPBridgeViewController never sets it, so the popup would be
 * swallowed before WebViewDelegationHandler's createWebViewWith ever ran. The
 * prompt puts the web route behind a fresh tap, which always works, on the web
 * build too.
 *
 * Returns a cancel function; calling it disarms the race and guarantees no
 * callback afterwards.
 */
function attemptPaymentHandoff(method, options = {}) {
  const {
    win = typeof window !== 'undefined' ? window : null,
    doc = typeof document !== 'undefined' ? document : null,
    timeoutMs = PAYMENT_HANDOFF_MS,
    onInstructions = () => {},
    onNoHandoff = () => {},
  } = options;

  const routes = paymentRoutes(method);
  const { appUrl, webUrl, instructions } = routes;
  const noop = () => {};
  if (!win || typeof win.open !== 'function') return noop;

  // No app to hand off to. Whatever is left IS the route, and it is taken
  // inside the tap rather than raced against anything.
  if (!appUrl) {
    if (webUrl) {
      win.open(webUrl, '_blank', 'noopener,noreferrer');
      return noop;
    }
    // Zelle. The instructions used to be passed to showToast and then
    // immediately overwritten by the next showToast call in the same block, so
    // the one method that is nothing BUT instructions displayed none of them.
    if (instructions) onInstructions(routes);
    return noop;
  }

  win.open(appUrl, '_blank');

  let settled = false;
  let timer = null;

  const cleanup = () => {
    if (timer !== null && typeof win.clearTimeout === 'function') win.clearTimeout(timer);
    timer = null;
    if (doc && typeof doc.removeEventListener === 'function') {
      doc.removeEventListener('visibilitychange', onBackgrounded);
    }
    if (typeof win.removeEventListener === 'function') {
      win.removeEventListener('pagehide', onBackgrounded);
    }
  };

  function onBackgrounded(event) {
    if (settled) return;
    // visibilitychange fires on the way back too. Only the hidden edge means
    // something replaced the app on screen.
    if (event && event.type === 'visibilitychange' && doc && doc.visibilityState !== 'hidden') return;
    settled = true;
    cleanup();
  }

  if (doc && typeof doc.addEventListener === 'function') {
    doc.addEventListener('visibilitychange', onBackgrounded);
  }
  if (typeof win.addEventListener === 'function') {
    win.addEventListener('pagehide', onBackgrounded);
  }

  if (typeof win.setTimeout === 'function') {
    timer = win.setTimeout(() => {
      timer = null;
      if (settled) return;
      settled = true;
      const stillOnScreen = !doc || doc.visibilityState !== 'hidden';
      cleanup();
      if (stillOnScreen) onNoHandoff(routes);
    }, timeoutMs);
  }

  return () => {
    if (settled) return;
    settled = true;
    cleanup();
  };
}

// Memoized VenueCard — unified design for both DMs and Flocks
const VenueCard = React.memo(({ venue, onViewDetails, onVote, colors: c, Icons: I, getCategoryColor: gcc }) => {
  const rating = venue.stars || venue.rating || null;
  const price = venue.price || (venue.price_level ? '$'.repeat(venue.price_level) : null);
  const address = venue.addr || venue.formatted_address || '';
  // Real crowd data only. This used to be
  //   Math.round(20 + (name.charCodeAt(0) * 37) % 60)
  // which is a number invented from the venue's first letter and rendered to
  // the user as a measurement. It is also why surfaces disagreed about the
  // same venue. No score yet means no crowd row, exactly as Birdie's cards do.
  const crowd = typeof venue.crowd === 'number' ? venue.crowd : null;
  const crowdColor = crowdColorFor(crowd);
  const crowdInk = crowdInkFor(crowd, colors);
  return (
    <div style={{
      backgroundColor: 'var(--bg-card-solid)',
      borderRadius: '16px',
      overflow: 'hidden',
      boxShadow: '0 4px 20px rgba(0,0,0,0.12)',
      border: '1px solid var(--border-subtle)',
      width: '100%',
      maxWidth: '280px',
      animation: 'cardSlideIn 0.4s ease-out'
    }}>
      {/* A venue with no photo used to leave a blank block. The placeholder is
          Birdie in cream, deliberately low contrast so it recedes next to the
          real photographs beside it. Only on the LARGE slots: at the 44px
          thumbnail size in list rows a photograph is mud, and those keep their
          letter. */}
      <img
        src={venue.photo_url ? resolveVenuePhoto(venue.photo_url) : '/marks/venue-placeholder.jpg'}
        alt={venue.photo_url ? venue.name : ''}
        loading="lazy"
        style={{ width: '100%', height: '160px', objectFit: 'cover', display: 'block' }}
        onError={(e) => { e.target.src = '/marks/venue-placeholder.jpg'; }}
      />

      <div style={{ padding: '14px' }}>
        <h4 style={{ fontSize: 'var(--t-body)', fontWeight: '600', color: c.navy, margin: '0 0 4px' }}>{venue.name}</h4>

        {address && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '10px' }}>
            {I.mapPin(c.textSecondary, 12)}
            <span style={{ fontSize: 'var(--t-meta)', color: 'var(--text-secondary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{address}</span>
          </div>
        )}

        <div style={{ display: 'flex', gap: '12px', marginBottom: '12px' }}>
          {price && <span style={{ fontSize: 'var(--t-meta)', color: c.navy, fontWeight: '500' }}>{price}</span>}
          {rating && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '3px' }}>
              {I.starFilled('#fbbf24', 12)}
              <span style={{ fontSize: 'var(--t-meta)', color: c.navy, fontWeight: '500' }}>{rating}</span>
            </div>
          )}
        </div>

        {crowd != null && (
          <div style={{ backgroundColor: 'var(--bg-tertiary)', borderRadius: '12px', padding: '10px 12px', marginBottom: '12px', border: '1px solid var(--border-default)' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '6px' }}>
              <span style={{ fontSize: 'var(--t-meta)', color: 'var(--text-secondary)', fontWeight: '500' }}>{crowdLabelFor(crowd)}{crowdLabelFor(crowd) ? ' for this spot' : ''}</span>
              <div style={{ backgroundColor: `${crowdColor}20`, color: crowdInk, padding: '2px 8px', borderRadius: '10px', fontSize: 'var(--t-meta)', fontWeight: '500' }}>{crowd}%</div>
            </div>
            <div style={{ width: '100%', height: '6px', backgroundColor: 'var(--pill-bg)', borderRadius: '3px', overflow: 'hidden' }}>
              <div style={{ height: '100%', width: `${crowd}%`, backgroundColor: crowdColor, borderRadius: '3px', transition: 'width 0.5s ease-out' }} />
            </div>
          </div>
        )}

        <div style={{ display: 'flex', gap: '8px' }}>
          {(venue.place_id || venue.id) && (
            /* stopPropagation on both buttons: a venue card posted into a chat
               is wrapped in a tap target that opens the reaction and report
               row, so a tap on View Details or Vote must not also toggle it. */
            <button className="hit44 glass-btn glass-secondary" onClick={(e) => { e.stopPropagation(); onViewDetails(); }} style={{ flex: 1, padding: '10px', borderRadius: '10px', border: `2px solid ${c.navy}`, backgroundColor: 'var(--bg-card-solid)', color: c.navy, fontSize: 'var(--t-meta)', fontWeight: '600', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '4px', transition: 'opacity 0.2s ease' }}>
              {I.eye(c.navy, 14)} View Details
            </button>
          )}
          <button className="hit44 glass-btn glass-navy" onClick={(e) => { e.stopPropagation(); const btn = e.currentTarget; if (!btn.classList.contains('btn-confirmed')) { btn.classList.add('btn-confirmed'); setTimeout(() => btn.classList.remove('btn-confirmed'), 1100); } onVote(); }} style={{ flex: 1, padding: '10px', borderRadius: '10px', border: 'none', background: `linear-gradient(135deg, ${c.navy}, ${c.navyMid})`, color: 'white', fontSize: 'var(--t-meta)', fontWeight: '600', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '4px', boxShadow: '0 2px 8px rgba(13,40,71,0.10)', transition: 'opacity 0.2s ease', position: 'relative', overflow: 'hidden' }}>
              {I.vote('white', 14)} Vote for This
            </button>
        </div>
      </div>
    </div>
  );
});

// =============================================================================
// MapLibre GL JS — Snap Map-style vector basemap (smooth GPU-rendered)
// Prefers MapTiler Streets v2 Dark when REACT_APP_MAPTILER_KEY is set
// (denser POIs, road hierarchies, neighborhood labels). Falls back to
// CARTO Dark Matter (free, no key) when the env var is missing.
// =============================================================================
const MAPTILER_KEY = process.env.REACT_APP_MAPTILER_KEY;
// basic-v2 instead of streets-v2 (2026-08-12): streets renders every POI,
// transit stop, and neighborhood label Google-style, which buried Flock's own
// venue markers in basemap noise. Basic keeps roads/water/districts legible
// and lets OUR pins be the loudest thing on the map.
const DARK_VECTOR_STYLE = MAPTILER_KEY
  ? `https://api.maptiler.com/maps/basic-v2-dark/style.json?key=${MAPTILER_KEY}`
  : 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json';
// Light-mode basemap (2026-07 redesign): the always-dark map read as a "weird
// overlay" inside the cream app. Basic light in light mode; positron fallback.
const LIGHT_VECTOR_STYLE = MAPTILER_KEY
  ? `https://api.maptiler.com/maps/basic-v2/style.json?key=${MAPTILER_KEY}`
  : 'https://basemaps.cartocdn.com/gl/positron-gl-style/style.json';
const isAppDark = () => document.documentElement.getAttribute('data-theme') === 'dark';
// Pass `dark` explicitly when you have it from React state; omit it to read the
// live <html data-theme> (used at map construction, before any effect runs).
const ROADMAP_STYLE = (dark) => ((dark === undefined ? isAppDark() : dark) ? DARK_VECTOR_STYLE : LIGHT_VECTOR_STYLE);
// Satellite: MapTiler "hybrid" (imagery + roads + place labels overlaid), and
// ONLY that. Null when there is no key, which is what SATELLITE_AVAILABLE below
// reads to hide the toggle rather than offer a button that cannot answer.
//
// WHY THERE IS NO KEYLESS FALLBACK ANY MORE. This used to fall back to raster
// tiles from server.arcgisonline.com, requested with no API key and no Esri
// account. Esri's basemaps are not free for commercial use, so that was a
// licensing exposure before it was ever a billing one — and it was the only
// outbound host in the app with that shape (which is why it needed its own CSP
// allowlist entry). It was already dead in every build that ships: Vercel and
// Codemagic both set REACT_APP_MAPTILER_KEY, so the MapTiler branch always won
// and the Esri branch had not served a tile in production. What it did still do
// was ship unlicensed-request code in a PUBLIC repo, where anyone who clones
// Flock without a MapTiler key and taps the satellite toggle starts making them
// against Esri's servers under their own IP. Removing the branch costs
// production nothing and stops handing that to contributors.
//
// The roadmap basemap keeps its keyless CARTO fallback — CARTO's Dark Matter and
// Positron are openly licensed for this, which is exactly the property Esri's
// imagery lacks. There is no comparable free satellite source, so the honest
// keyless answer is "no satellite", not "someone else's imagery".
const SATELLITE_STYLE = MAPTILER_KEY
  ? `https://api.maptiler.com/maps/hybrid/style.json?key=${MAPTILER_KEY}`
  : null;
const SATELLITE_AVAILABLE = !!SATELLITE_STYLE;

// AI crowd heatmap paint — matches the old Google HeatmapLayer gradient/radius/opacity.
// MapLibre heatmap-intensity: 2 ≈ Google maxIntensity: 0.5 (1/0.5 = 2× per-point contribution).
const VENUE_HEAT_PAINT = {
  'heatmap-weight': ['coalesce', ['get', 'weight'], 0.5],
  /* Radius and intensity follow zoom so the heat reads as one continuous
     field over the area instead of isolated blobs. At city zoom the points
     are pushed wide enough to merge; street zoom pulls them back in so a hot
     venue localizes to its block. The WEIGHTS stay the real crowd scores
     (score/100, set where the features are built) — coverage comes from
     radius, never from inflating what a venue actually says. */
  'heatmap-intensity': ['interpolate', ['linear'], ['zoom'], 8, 5, 12, 4, 15, 3.2, 18, 2.6],
  'heatmap-radius': ['interpolate', ['linear'], ['zoom'], 8, 120, 11, 95, 13, 72, 15, 55, 18, 40],
  'heatmap-opacity': 0.85,
  'heatmap-color': [
    'interpolate', ['linear'], ['heatmap-density'],
    0,    'rgba(0, 0, 0, 0)',
    /* A quiet venue used to vanish below the 0.1 stop; low scores now stay
       visibly cool instead of invisible. */
    0.03, 'rgba(34, 197, 94, 0.4)',
    0.1,  'rgba(34, 197, 94, 0.6)',
    0.2,  'rgba(34, 197, 94, 0.7)',
    0.3,  'rgba(160, 220, 40, 0.75)',
    0.4,  'rgba(250, 204, 21, 0.8)',
    0.5,  'rgba(251, 191, 36, 0.82)',
    0.6,  'rgba(245, 158, 11, 0.85)',
    0.7,  'rgba(249, 115, 22, 0.88)',
    0.8,  'rgba(239, 68, 68, 0.9)',
    0.9,  'rgba(220, 38, 38, 0.94)',
    1,    'rgba(185, 28, 28, 0.97)',
  ],
};

// Add accuracy ring + venue heatmap + 3D buildings.
// Inserts heat UNDER the first symbol layer so road/place labels stay readable
// on top of the heat. 3D building extrusion uses the basemap's existing
// building vector tiles (free, no extra fetch) — gives the map Snap-Map-style
// city depth when zoomed in.
function addOverlayLayers(map) {
  const layers = map.getStyle().layers || [];
  const firstSymbolId = layers.find(l => l.type === 'symbol')?.id;

  if (!map.getSource('user-accuracy')) {
    map.addSource('user-accuracy', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
    map.addLayer({ id: 'user-accuracy-fill', type: 'fill', source: 'user-accuracy', paint: { 'fill-color': '#3b82f6', 'fill-opacity': 0.1 } }, firstSymbolId);
    map.addLayer({ id: 'user-accuracy-line', type: 'line', source: 'user-accuracy', paint: { 'line-color': '#3b82f6', 'line-opacity': 0.3, 'line-width': 1 } }, firstSymbolId);
  }
  if (!map.getSource('venue-heat')) {
    map.addSource('venue-heat', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
    map.addLayer({ id: 'venue-heat', type: 'heatmap', source: 'venue-heat', paint: VENUE_HEAT_PAINT }, firstSymbolId);
  }

  // 3D building extrusion. Reuses whichever building source-layer the basemap
  // exposes (CARTO/OMT call it 'building'). Skipped when basemap doesn't ship
  // building geometry (e.g. raster satellite style).
  if (!map.getLayer('flock-3d-buildings')) {
    const buildingLayer = layers.find(l => l['source-layer'] === 'building' && (l.type === 'fill' || l.type === 'fill-extrusion'));
    if (buildingLayer) {
      try {
        map.addLayer({
          id: 'flock-3d-buildings',
          source: buildingLayer.source,
          'source-layer': 'building',
          type: 'fill-extrusion',
          minzoom: 14,
          paint: {
            'fill-extrusion-color': '#243651',
            'fill-extrusion-height': [
              'interpolate', ['linear'], ['zoom'],
              14, 0,
              16, ['coalesce', ['get', 'render_height'], ['get', 'height'], 8],
            ],
            'fill-extrusion-base': ['coalesce', ['get', 'render_min_height'], ['get', 'min_height'], 0],
            'fill-extrusion-opacity': 0.75,
          },
        }, firstSymbolId);
      } catch {}
    }
  }
}

// True-meters circle as a GeoJSON polygon for the user's accuracy ring
function metersCirclePolygon(lat, lng, radiusMeters, points = 64) {
  const coords = [];
  const earthR = 6378137;
  const latRad = (lat * Math.PI) / 180;
  for (let i = 0; i <= points; i++) {
    const angle = (i / points) * Math.PI * 2;
    const dLat = (radiusMeters * Math.cos(angle)) / earthR;
    const dLng = (radiusMeters * Math.sin(angle)) / (earthR * Math.cos(latRad));
    coords.push([lng + (dLng * 180) / Math.PI, lat + (dLat * 180) / Math.PI]);
  }
  return { type: 'Feature', geometry: { type: 'Polygon', coordinates: [coords] }, properties: {} };
}

/* Pins stacked on one point are one pin: only the top one is visible or
   tappable, and hiding or shrinking the rest was ruled out. So overlapping
   pins are displaced a few screen pixels around their shared centroid — every
   venue keeps a full-size pin, at the cost of a little positional accuracy.
   The offsets are deterministic (members sorted by place_id, laid out on a
   Vogel spiral) so a pin sits in the same spot on every render instead of
   jittering, and the whole pass re-runs on zoomend only: as the user zooms in
   the true positions separate, groups dissolve, and each pin snaps back to
   its real location. O(n²) over ≤ ~20 markers, so no per-frame work. */
const PIN_OVERLAP_PX = 46; // pin body is 44px; closer than this and they stack
const PIN_RING_PX = 40;    // spacing between displaced neighbours

const venueMatchesCategory = (v, filterCategory) => {
  const t = (v.types || []).join(' ').toLowerCase();
  const nm = (v.name || '').toLowerCase();
  let show = true;
  if (filterCategory && filterCategory !== 'All') {
    if (filterCategory === 'Food') {
      show = t.includes('restaurant') || t.includes('cafe') || t.includes('food') || t.includes('bakery') || t.includes('meal') || t.includes('pizza') || t.includes('diner') || t.includes('bar') || t.includes('juice') || t.includes('smoothie') || t.includes('brunch') || t.includes('breakfast') || v.category === 'Food';
    } else if (filterCategory === 'Nightlife') {
      show = t.includes('bar') || t.includes('night_club') || t.includes('club') || t.includes('liquor') || t.includes('lounge') || v.category === 'Nightlife';
    } else if (filterCategory === 'Live Music') {
      show = t.includes('music') || t.includes('concert') || t.includes('performing_arts') || nm.includes('music') || nm.includes('jazz') || v.category === 'Live Music';
    } else if (filterCategory === 'Sports') {
      show = t.includes('stadium') || t.includes('gym') || t.includes('sports') || t.includes('bowling') || t.includes('fitness') || nm.includes('sport') || v.category === 'Sports';
    }
  }
  return show;
};

const applyCategoryFilter = (map, markers, filterCategory, setFilterHidesAll) => {
  let visible = 0;
  const heatFeatures = [];
  markers.forEach(({ el, venue: v }) => {
    const show = venueMatchesCategory(v, filterCategory);
    el.style.display = show ? '' : 'none';
    if (!show) return;
    visible += 1;
    const loc = v.location;
    if (loc?.latitude && loc?.longitude && typeof v.crowd === 'number') {
      heatFeatures.push({ type: 'Feature', geometry: { type: 'Point', coordinates: [loc.longitude, loc.latitude] }, properties: { weight: v.crowd / 100 } });
    }
  });
  const heatSrc = map && map.getSource ? map.getSource('venue-heat') : null;
  if (heatSrc) heatSrc.setData({ type: 'FeatureCollection', features: heatFeatures });
  setFilterHidesAll(markers.length > 0 && visible === 0);
};

function declutterMarkers(map, markerEntries) {
  if (!map) return;
  const entries = markerEntries.filter(({ venue }) => venue.location?.latitude && venue.location?.longitude);
  if (entries.length === 0) return;
  let pts;
  try {
    pts = entries.map(({ venue }) => map.project([venue.location.longitude, venue.location.latitude]));
  } catch { return; } // container not measured yet — the next zoomend re-runs
  // Union-find over pairs closer than one pin body.
  const parent = entries.map((_, i) => i);
  const find = (i) => (parent[i] === i ? i : (parent[i] = find(parent[i])));
  for (let i = 0; i < pts.length; i++) {
    for (let j = i + 1; j < pts.length; j++) {
      const dx = pts[i].x - pts[j].x;
      const dy = pts[i].y - pts[j].y;
      if (dx * dx + dy * dy < PIN_OVERLAP_PX * PIN_OVERLAP_PX) parent[find(j)] = find(i);
    }
  }
  const groups = new Map();
  entries.forEach((_, i) => {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(i);
  });
  const GOLDEN_ANGLE = 2.399963229728653;
  /* Spiral slots are only spaced against their OWN group, but a big group's
     outer arm reaches 40·√k px from its centroid — measured live, a
     17-member downtown cluster parked a pin 16px from a venue 129px away
     that was never in its group. So placement is checked against every pin
     already placed, across groups. Singletons go first: they never move, so
     they must be in the occupied set before any spiral slot is chosen near
     them, and no arm can cover a lone pin standing exactly on its venue. */
  const placedPts = [];
  const multiGroups = [];
  groups.forEach((idxs) => {
    if (idxs.length === 1) {
      // Alone again (or always was): the pin sits exactly where the venue is.
      const { marker, venue } = entries[idxs[0]];
      marker.setLngLat([venue.location.longitude, venue.location.latitude]);
      placedPts.push(pts[idxs[0]]);
      return;
    }
    multiGroups.push(idxs);
  });
  multiGroups.forEach((idxs) => {
    // Deterministic member order — same venue, same offset, every render.
    idxs.sort((a, b) => String(entries[a].venue.place_id || entries[a].venue.id).localeCompare(String(entries[b].venue.place_id || entries[b].venue.id)));
    const cx = idxs.reduce((s, i) => s + pts[i].x, 0) / idxs.length;
    const cy = idxs.reduce((s, i) => s + pts[i].y, 0) / idxs.length;
    // One shared slot cursor per group: a slot skipped for landing on a
    // foreign pin stays skipped, so the assignment stays deterministic.
    // Within a group the spiral itself keeps neighbours >= PIN_RING_PX apart
    // (k0→k1 is exactly PIN_RING_PX, strict < below admits it), so the
    // occupancy test only ever rejects slots that hit OTHER pins. Bounded:
    // the radius grows with every skip, so the arm always escapes a crowded
    // patch; the guard is a hard stop, not the normal exit.
    let k = 0;
    // Parameterized so the loop below carries no closure over its own
    // mutating coordinates (CRA builds with CI=true, where no-loop-func
    // is fatal; Vercel deploy 2026-08-18 died on exactly that).
    const collides = (qx, qy) => placedPts.some((p) => (p.x - qx) * (p.x - qx) + (p.y - qy) * (p.y - qy) < PIN_RING_PX * PIN_RING_PX);
    idxs.forEach((i) => {
      let x, y;
      let guard = 0;
      do {
        const r = PIN_RING_PX * Math.sqrt(k); // k=0 holds the centroid
        const a = k * GOLDEN_ANGLE;
        x = cx + r * Math.cos(a);
        y = cy + r * Math.sin(a);
        k += 1;
        guard += 1;
      } while (guard < idxs.length + 60 && collides(x, y));
      entries[i].marker.setLngLat(map.unproject([x, y]));
      placedPts.push({ x, y });
    });
  });
}

const MapLibreMapView = React.memo(({ venues, filterCategory, userLocation, activeVenue, setActiveVenue, getCategoryColor, pickingVenueForCreate, setPickingVenueForCreate, setSelectedVenueForCreate, setCurrentScreen, openVenueDetail, flockMemberLocations, calcDistance, ownerPlaceId = null, initialCenter = null, followUser = true, locationAllowed = true }) => {
  const mapRef = useRef(null);
  const mapRootRef = useRef(null);   // outermost node — see the attribution note in init
  const mapInstanceRef = useRef(null);
  const markersRef = useRef([]); // [{ marker, el, venue }]
  const userMarkerRef = useRef(null);
  const userElRef = useRef(null);
  const memberMarkersRef = useRef({}); // userId -> { marker, popup }
  const photoCacheRef = useRef({}); // place_id -> dataURL
  const prevActiveRef = useRef(null);
  const watchIdRef = useRef(null);
  const mapLibreRef = useRef(null); // holds the maplibre-gl module after dynamic import
  const venuesRef = useRef([]);     // latest venues for non-React consumers (toggleMapType, etc.)
  const fittedKeyRef = useRef(null); // result set the viewport was last framed to
  const [mapReady, setMapReady] = useState(false);
  // The category filter hid every pin on the map. Rendered as a sentence,
  // because an empty map reads as broken.
  const [filterHidesAll, setFilterHidesAll] = useState(false);
  const filterCategoryRef = useRef(filterCategory);
  // Same guard as the map constructor below: a stored 'hybrid' is only honoured
  // while there is a satellite style to honour it with.
  const [mapType, setMapType] = useState(() => (
    SATELLITE_AVAILABLE && localStorage.getItem('flock_map_type') === 'hybrid' ? 'hybrid' : 'roadmap'
  ));
  /* The basemap follows the app theme. It used to be chosen ONCE, at map
     construction, so flipping to dark mode left three quarters of Discover as a
     bright blue-and-cream rectangle under navy chrome. The style is now swapped
     whenever the theme changes, and every marker colour below is read from the
     matching palette instead of the module-level light-mode constant. */
  const { isDark: mapIsDark } = useTheme();
  const mapPalette = mapIsDark ? colorsDark : colorsLight;
  const appliedDarkRef = useRef(null);

  const DEFAULT_ZOOM = 12;

  // ---------- helpers ----------
  // Resolves null when we do not know where the user is, and null means null.
  // Both branches used to resolve a fixed point in Bethlehem, Pennsylvania, so
  // a phone that declined the permission opened a map centred confidently on a
  // town it had never been to. An unknown location now opens the wide view
  // below, and the map re-pans the moment permission is granted.
  const getUserLocation = () => new Promise((resolve) => {
    if (geolocationAvailable()) {
      getCurrentPosition(
        (p) => resolve({ lat: p.coords.latitude, lng: p.coords.longitude }),
        () => resolve(null),
        { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 },
      );
    } else {
      resolve(null);
    }
  });

  // Where the map opens when nothing knows where the user is: the whole
  // country, zoomed out far enough that it reads as "pick somewhere" rather
  // than as a claim about where you are standing.
  const UNKNOWN_LOCATION_VIEW = { lat: 39.83, lng: -98.58, zoom: 3.2 };

  // SVG fallback pin (no photo). Inverted on the dark basemap: a navy pin body
  // on dark tiles was a hole in the map.
  const buildPinSvg = useCallback((isActive, category) => {
    const body = mapIsDark
      ? (isActive ? '#6d9ac3' : '#f1ede0')
      : (isActive ? '#2d5a87' : '#1e293b');
    const edge = mapIsDark ? '#0b1220' : '#f1ede0';
    const disc = mapIsDark ? '#0f172a' : '#ffffff';
    const initialMap = { Food: 'F', Nightlife: 'N', 'Live Music': 'M', Sports: 'S' };
    // Own-property lookup only. `initialMap[category]` answers 'constructor'
    // and '__proto__' off Object.prototype with something truthy, and the
    // result is interpolated straight into the innerHTML string below, so a
    // venue whose category arrived as one of those names drew a pin labelled
    // with the source of a native function. Same rule, same reason as `own()`
    // in website/ModerationDashboard.js.
    const initial = (Object.prototype.hasOwnProperty.call(initialMap, category) && initialMap[category]) || 'P';
    return `<svg aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 42">` +
      `<defs><filter id="s" x="-20%" y="-10%" width="140%" height="140%"><feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity="0.35"/></filter></defs>` +
      `<path d="M16 0C7.16 0 0 7.16 0 16c0 12 16 26 16 26s16-14 16-26C32 7.16 24.84 0 16 0z" fill="${body}" stroke="${edge}" stroke-width="2" filter="url(#s)"/>` +
      `<circle cx="16" cy="14.5" r="9" fill="${disc}"/>` +
      `<text x="16" y="18.5" text-anchor="middle" font-size="13" font-weight="bold" font-family="Hanken Grotesk,sans-serif" fill="${body}">${initial}</text>` +
      `</svg>`;
  }, [mapIsDark]);

  // Circular photo pin via canvas (same trick as the old impl, returns dataURL)
  const buildPhotoPin = useCallback((photoUrl, isActive) => {
    const size = isActive ? 54 : 44;
    const border = isActive ? 3.5 : 2.5;
    const borderColor = isActive ? (mapIsDark ? '#6d9ac3' : '#2d5a87') : '#f1ede0';
    return new Promise((resolve) => {
      const canvas = document.createElement('canvas');
      const dpr = 2;
      canvas.width = size * dpr;
      canvas.height = size * dpr;
      const ctx = canvas.getContext('2d');
      ctx.scale(dpr, dpr);
      const r = size / 2;
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        ctx.beginPath();
        ctx.arc(r, r, r - 0.5, 0, Math.PI * 2);
        ctx.fillStyle = borderColor;
        ctx.fill();
        ctx.beginPath();
        ctx.arc(r, r, r - border, 0, Math.PI * 2);
        ctx.clip();
        const aspect = img.width / img.height;
        let sx = 0, sy = 0, sw = img.width, sh = img.height;
        if (aspect > 1) { sx = (img.width - img.height) / 2; sw = img.height; }
        else { sy = (img.height - img.width) / 2; sh = img.width; }
        ctx.drawImage(img, sx, sy, sw, sh, border, border, size - border * 2, size - border * 2);
        resolve(canvas.toDataURL('image/png'));
      };
      img.onerror = () => resolve(null);
      img.src = photoUrl;
    });
  }, [mapIsDark]);

  // Category ring colour. This used to read the module-level `colors`, which is
  // the LIGHT palette regardless of theme — so on the dark basemap the rings
  // were navy on near-black and the pins lost their edge entirely.
  const categoryRingColor = useCallback((cat) => {
    switch (cat) {
      case 'Food': return mapPalette.food;
      case 'Nightlife': return mapPalette.nightlife;
      case 'Live Music': return mapPalette.music;
      case 'Sports': return mapPalette.sports;
      default: return mapPalette.steel;
    }
  }, [mapPalette]);

  // Build a marker DOM element (pin or photo). The OUTER el is owned by MapLibre
  // (it sets transform every frame), so all visual styling + transitions live on
  // an INNER div. Touching transform on the outer el causes pin lag / wrong position.
  const buildMarkerEl = useCallback((venue, isActive) => {
    const el = document.createElement('div');
    el.className = 'mlb-venue-marker';
    el.style.cursor = 'pointer';
    el.style.display = 'flex';
    el.style.flexDirection = 'column';
    el.style.alignItems = 'center';
    // No transition / transform on the outer el — MapLibre owns it.

    const inner = document.createElement('div');
    inner.className = 'mlb-marker-inner';
    inner.style.transition = 'width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease';
    inner.style.willChange = 'auto';
    const size = isActive ? 54 : 44;
    inner.style.width = size + 'px';
    inner.style.height = size + 'px';
    inner.style.display = 'block';

    const ring = categoryRingColor(venue.category);
    const applyPhotoStyle = () => {
      inner.style.backgroundSize = 'cover';
      inner.style.backgroundPosition = 'center';
      inner.style.borderRadius = '50%';
      inner.style.boxShadow = `0 0 0 3px ${ring}, 0 4px 14px rgba(0,0,0,0.35)`;
    };

    const cached = photoCacheRef.current[venue.place_id];
    if (cached) {
      inner.style.backgroundImage = `url("${cached}")`;
      applyPhotoStyle();
    } else if (venue.photo_url) {
      const svg = buildPinSvg(isActive, venue.category);
      inner.innerHTML = svg;
      const svgEl = inner.querySelector('svg');
      if (svgEl) { svgEl.setAttribute('width', size); svgEl.setAttribute('height', Math.round(size * 1.32)); }
      buildPhotoPin(venue.photo_url, isActive).then(dataUrl => {
        if (dataUrl) {
          photoCacheRef.current[venue.place_id] = dataUrl;
          inner.innerHTML = '';
          inner.style.backgroundImage = `url("${dataUrl}")`;
          applyPhotoStyle();
        }
      });
    } else {
      const svg = buildPinSvg(isActive, venue.category);
      inner.innerHTML = svg;
      const svgEl = inner.querySelector('svg');
      if (svgEl) { svgEl.setAttribute('width', size); svgEl.setAttribute('height', Math.round(size * 1.32)); }
    }
    el.appendChild(inner);

    // Name + rating label (Apple-Maps-style). Hidden by default; CSS shows it
    // when the map container reaches data-zoom-tier="hi".
    //
    // BOTH INTERPOLATED VALUES GO THROUGH escapeHtml, and neither used to.
    //
    // The name was `.replace(/[<>]/g, '')`. Stripping is not escaping: it
    // leaves `&`, `"` and `'` alone, so a venue whose name contains `&amp;` or
    // `&copy;` is DISPLAYED decoded (the innerHTML parser resolves the
    // reference), i.e. the label shows a character the business does not have
    // in its name. escapeHtml, defined near the top of this file, is what the
    // other two innerHTML sinks here use, and its comment says why: "This must
    // be safe on its own — do NOT rely on upstream stripHtml".
    //
    // The rating was worse, and it is the reason this is a change rather than
    // a tidy-up: the old ternary called `.toFixed(1)` only when the value HAD
    // a toFixed, and interpolated it VERBATIM when it did not. A rating that
    // arrives as a string rather than a number — which is what every non-Google
    // path in this app hands us, `venue.stars` included — was raw HTML in an
    // innerHTML sink with no filter of any kind in front of it. It is coerced
    // to a number here so the non-numeric branch cannot exist, and escaped
    // anyway.
    const label = document.createElement('div');
    label.className = 'mlb-marker-label';
    // System star via starSvgString, not a raw glyph: the label is innerHTML
    // so JSX cannot reach it, but the geometry must still be the icon set's.
    const ratingValue = Number(venue.rating || venue.stars);
    const ratingHtml = Number.isFinite(ratingValue) && ratingValue > 0
      ? `<span class="mlb-label-rating">${starSvgString(12)} ${escapeHtml(ratingValue.toFixed(1))}</span>`
      : '';
    label.innerHTML = `<span class="mlb-label-name">${escapeHtml(venue.name || '')}</span>${ratingHtml}`;
    el.appendChild(label);

    return el;
  }, [buildPinSvg, buildPhotoPin, categoryRingColor]);

  // ---------- init map (once) ----------
  useEffect(() => {
    if (!mapRef.current || mapInstanceRef.current) return;
    let cancelled = false;
    let resizeObs = null;
    const init = async () => {
      // The stylesheet travels with the engine, not with App.js. Both requests
      // start together so the CSS costs no extra round trip, and the map is
      // only built once the styles have landed: maplibre draws its controls,
      // attribution and popups as bare DOM, so constructing it first would
      // paint an unstyled control stack for however long the sheet took.
      //
      // Its failure is swallowed on purpose. A chunk that will not load is a
      // reason to show a map with plain controls, never a reason to show no
      // map, and the attribution stays legible either way. Order relative to
      // index.css is unchanged by this: an async CSS chunk is appended to
      // <head> after the entry stylesheet whichever import fetched it, so the
      // two `.maplibregl-ctrl-attrib` overrides in index.css still resolve
      // exactly as they did.
      const styleSheetReady = import('maplibre-gl/dist/maplibre-gl.css').catch(() => {});
      const maplibregl = (await import('maplibre-gl')).default;
      await styleSheetReady;
      mapLibreRef.current = maplibregl;
      if (cancelled) return;
      // A caller that already knows where the map should open (the venue
      // dashboard passes the venue itself) skips the geolocation prompt.
      //
      // So does a person who turned Location services off in Settings. That
      // switch used to write a flag, print "Location is turned off" on its own
      // row, and change nothing: this effect asked anyway, and so did the
      // Discover tab. A switch that reports a state it does not enforce is
      // worse than no switch, because the person believes they have already
      // handled it. UNKNOWN_LOCATION_VIEW is the same fallback a denied prompt
      // gets, so the map opens rather than sitting blank.
      const located = (initialCenter || !locationAllowed)
        ? (initialCenter ? { lat: initialCenter.lat, lng: initialCenter.lng } : null)
        : await getUserLocation();
      const userLoc = located || UNKNOWN_LOCATION_VIEW;
      if (cancelled) return;
      // Same expression as the mapType useState above, and it has to stay the
      // same one: a stored 'hybrid' from a build that HAD a MapTiler key must
      // not construct the map with a null style in one that does not.
      // localStorage outlives the env var.
      const savedMapType = SATELLITE_AVAILABLE && localStorage.getItem('flock_map_type') === 'hybrid'
        ? 'hybrid' : 'roadmap';

      // A remote basemap style (bad/missing MapTiler key, network, 403) must
      // NOT take the whole app down. A synchronous failure constructing the map
      // is caught here; the async style/tile fetch failures are swallowed by the
      // 'error' listener below. Either way Discover degrades to an empty map
      // instead of throwing up to the root error boundary.
      let map;
      try {
        map = new maplibregl.Map({
          container: mapRef.current,
          style: savedMapType === 'roadmap' ? ROADMAP_STYLE() : SATELLITE_STYLE,
          center: [userLoc.lng, userLoc.lat],
          zoom: located ? DEFAULT_ZOOM : UNKNOWN_LOCATION_VIEW.zoom,
          minZoom: 3,
          maxZoom: 18,
          // Attribution added manually below at bottom-left (compact) so it
          // never collides with the View-All pill anchored bottom-right.
          attributionControl: false,
          // Snap-style smoothness
          fadeDuration: 200,
          antialias: true,
        });
      } catch (err) {
        console.warn('[Map] Failed to initialize basemap:', err?.message || err);
        return;
      }
      // Without a listener, MapLibre surfaces style/tile load errors (bad key,
      // network) rather than failing quietly. Swallow them so a broken basemap
      // leaves Discover usable.
      map.on('error', (e) => { console.warn('[Map]', e?.error?.message || e?.error || e); });
      map.addControl(new maplibregl.AttributionControl({ compact: true }), 'bottom-left');

      // KEYBOARD ORDER. MapLibre injects its control containers as the FIRST
      // children of the map element, and the map element is the first child of
      // this screen — so the attribution disclosure and its two credit links
      // were the first three tab stops a keyboard user hit, ahead of every
      // Flock control, every time the map was on screen. The credit still has
      // to be reachable (OSM's licence requires it), so it is moved rather than
      // removed: the container becomes the LAST child of the component root, so
      // it is the last tab stop instead of the first. It is absolutely
      // positioned bottom-left against a full-bleed parent either way, so it
      // does not move on screen. The compact disclosure toggle itself is
      // purely visual, so it drops out of the tab sequence (still clickable).
      try {
        const attrib = mapRef.current && mapRef.current.querySelector('.maplibregl-ctrl-bottom-left');
        if (attrib && mapRootRef.current) {
          mapRootRef.current.appendChild(attrib);
          const toggle = attrib.querySelector('.maplibregl-ctrl-attrib-button');
          if (toggle) toggle.setAttribute('tabindex', '-1');
        }
      } catch { /* attribution stays where MapLibre put it */ }
      mapInstanceRef.current = map;

      // Snappier scroll-wheel zoom — default 1/300 feels sluggish vs Snap Map.
      if (map.scrollZoom) {
        map.scrollZoom.setZoomRate(1 / 100);   // 3× faster per pixel
        map.scrollZoom.setWheelZoomRate(1 / 80); // 5× faster per wheel notch
      }

      // Track container size — MapLibre locks canvas dimensions at construction,
      // so if the parent flex layout settles AFTER init the canvas stays short
      // (leaves a navy gap below the map). ResizeObserver fixes that for good
      // and also handles orientation changes / window resize.
      if (typeof ResizeObserver !== 'undefined') {
        resizeObs = new ResizeObserver(() => { try { map.resize(); } catch {} });
        resizeObs.observe(mapRef.current);
      } else {
        // Fallback: nudge once after layout settles
        setTimeout(() => { try { map.resize(); } catch {} }, 0);
      }

      // Tier the map's container by zoom so CSS can scale + label markers
      // without re-rendering the React tree on every wheel notch.
      const applyZoomTier = () => {
        const z = map.getZoom();
        const container = mapRef.current;
        if (!container) return;
        // hi  → labels visible, full-size markers
        // mid → no labels, full-size
        // lo  → no labels, shrunk markers (zoomed-out density)
        const tier = z >= 15 ? 'hi' : z >= 13 ? 'mid' : 'lo';
        if (container.dataset.zoomTier !== tier) container.dataset.zoomTier = tier;
      };

      // Brighten native basemap POI labels (MapTiler's Streets v2 Dark dims them
      // hard, which is why the map feels emptier than Apple's). We bump opacity
      // and lower the minzoom so cafés/restaurants show earlier.
      const boostNativePoiLabels = () => {
        if (!isAppDark()) return; // pale-label boost is tuned for the dark basemap only
        const style = map.getStyle && map.getStyle();
        if (!style?.layers) return;
        for (const layer of style.layers) {
          if (layer.type !== 'symbol') continue;
          const id = layer.id || '';
          const sl = layer['source-layer'] || '';
          const looksPoi = /poi|place_label/i.test(id) || /poi|place/i.test(sl);
          if (!looksPoi) continue;
          try {
            map.setLayoutProperty(layer.id, 'visibility', 'visible');
            // Lower the zoom at which labels appear (default ~14 → 12.5)
            if (typeof layer.minzoom === 'number' && layer.minzoom > 12.5) {
              map.setLayerZoomRange(layer.id, 12.5, layer.maxzoom ?? 24);
            }
            map.setPaintProperty(layer.id, 'text-opacity', 0.95);
            map.setPaintProperty(layer.id, 'text-color', '#e2e8f0');
            map.setPaintProperty(layer.id, 'text-halo-color', 'rgba(15,23,42,0.85)');
            map.setPaintProperty(layer.id, 'text-halo-width', 1.4);
          } catch { /* layer may not support a property — ignore */ }
        }
      };

      map.on('load', () => {
        addOverlayLayers(map);
        applyZoomTier();
        boostNativePoiLabels();
        setMapReady(true);
      });

      // Re-apply both on style swap (roadmap ↔ satellite)
      map.on('styledata', () => {
        applyZoomTier();
        boostNativePoiLabels();
      });

      map.on('zoom', applyZoomTier);

      // Re-space overlapping pins once the zoom settles (never per frame).
      // Zooming in separates the true positions, so the displacement shrinks
      // to zero on its own; zooming out regroups them.
      map.on('zoomend', () => declutterMarkers(map, markersRef.current));

      // Click on empty map — clear active venue
      map.on('click', (e) => {
        if (e.originalEvent?.target?.closest?.('.mlb-venue-marker')) return;
        setActiveVenue(null);
      });

      // Re-pan when geolocation permission flips to granted
      if (followUser && navigator.permissions) {
        navigator.permissions.query({ name: 'geolocation' }).then((perm) => {
          perm.addEventListener('change', () => {
            if (perm.state === 'granted') {
              getCurrentPosition(
                (pos) => mapEase(map, { center: [pos.coords.longitude, pos.coords.latitude], zoom: DEFAULT_ZOOM }),
                () => {},
                { enableHighAccuracy: true, timeout: 8000, maximumAge: 0 },
              );
            }
          });
        }).catch(() => {});
      }
    };
    init();
    return () => { cancelled = true; if (resizeObs) resizeObs.disconnect(); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  /* setStyle throws away every source and layer the app added, so anything
     Flock owns has to go back on afterwards. Shared by the satellite toggle and
     the light/dark swap below. (HTML markers survive a style swap; sources and
     layers do not.) */
  const rehydrateAfterStyleSwap = useCallback((map) => {
    addOverlayLayers(map);
    // Re-feed accuracy data
    if (userLocation) {
      const src = map.getSource('user-accuracy');
      if (src) src.setData({ type: 'FeatureCollection', features: [metersCirclePolygon(userLocation.lat, userLocation.lng, userLocation.accuracy || 50)] });
    }
    // Re-feed heatmap data from current venues
    const heatSrc = map.getSource('venue-heat');
    if (heatSrc) {
      const features = (venuesRef.current || [])
        .filter(v => typeof v.crowd === 'number' && v.location?.latitude && v.location?.longitude)
        .map(v => ({ type: 'Feature', geometry: { type: 'Point', coordinates: [v.location.longitude, v.location.latitude] }, properties: { weight: v.crowd / 100 } }));
      heatSrc.setData({ type: 'FeatureCollection', features });
    }
  }, [userLocation]);

  // ---------- map type toggle (vector dark <-> satellite) ----------
  const toggleMapType = useCallback(async () => {
    const map = mapInstanceRef.current;
    if (!map) return;
    // No satellite style, no swap. The button is hidden in this case, so this is
    // the belt to that braces.
    if (!SATELLITE_AVAILABLE) return;
    const newType = mapType === 'roadmap' ? 'hybrid' : 'roadmap';
    setMapType(newType);
    localStorage.setItem('flock_map_type', newType);
    queueSync({ mapType: newType });
    map.setStyle(newType === 'roadmap' ? ROADMAP_STYLE(mapIsDark) : SATELLITE_STYLE);
    map.once('styledata', () => rehydrateAfterStyleSwap(map));
  }, [mapType, mapIsDark, rehydrateAfterStyleSwap]);

  // ---------- basemap follows the app theme ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map) return;
    // First pass records the theme the map was constructed with; only a real
    // change after that costs a style fetch.
    if (appliedDarkRef.current === null) { appliedDarkRef.current = mapIsDark; return; }
    if (appliedDarkRef.current === mapIsDark) return;
    appliedDarkRef.current = mapIsDark;
    if (mapType !== 'roadmap') return; // satellite imagery has no light/dark twin
    map.setStyle(ROADMAP_STYLE(mapIsDark));
    map.once('styledata', () => rehydrateAfterStyleSwap(map));
  }, [mapIsDark, mapReady, mapType, rehydrateAfterStyleSwap]);

  // ---------- user blue dot + accuracy ring ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map || !userLocation) return;
    const lng = userLocation.lng, lat = userLocation.lat;
    const acc = userLocation.accuracy || 50;

    // Blue dot — outer el is owned by MapLibre; pulse animations target the inner div.
    if (!userMarkerRef.current) {
      const el = document.createElement('div');
      el.style.width = '20px';
      el.style.height = '20px';
      const inner = document.createElement('div');
      inner.className = 'mlb-user-dot-inner';
      inner.style.width = '20px';
      inner.style.height = '20px';
      inner.style.borderRadius = '50%';
      inner.style.background = '#3b82f6';
      inner.style.border = '3px solid #fff';
      inner.style.boxShadow = '0 0 0 3px rgba(59,130,246,0.25)';
      inner.style.transition = 'box-shadow 0.4s ease';
      el.appendChild(inner);
      userElRef.current = inner; // pulse helper writes to the inner div
      const ml = mapLibreRef.current;
      if (!ml) return;
      userMarkerRef.current = new ml.Marker({ element: el, anchor: 'center' }).setLngLat([lng, lat]).addTo(map);
    } else {
      userMarkerRef.current.setLngLat([lng, lat]);
    }

    // Accuracy circle data
    const src = map.getSource('user-accuracy');
    if (src) {
      src.setData({ type: 'FeatureCollection', features: [metersCirclePolygon(lat, lng, acc)] });
    }
  }, [userLocation, mapReady]);

  // Live position tracking.
  //
  // THE THIRD DOOR INTO THE OS LOCATION PROMPT, and the one the Settings switch
  // did not close. watchPosition asks the device exactly as getCurrentPosition
  // does, so with "Location services" turned off this effect ran the moment the
  // map was ready and the prompt arrived anyway, over a map the person had
  // already told the app not to locate them on. The init effect above and the
  // Discover tab both check the switch; this one was written before it existed
  // and nothing pointed it at the flag.
  //
  // Same gate, same name, so the three doors are one rule rather than three
  // similar ones. followUser stays in the condition: it is the separate
  // question of whether THIS map is the one that follows you, and a venue
  // dashboard map answers no to it whatever the switch says.
  useEffect(() => {
    if (!mapReady || !followUser || !locationAllowed || !geolocationAvailable()) return;
    if (watchIdRef.current !== null) clearWatch(watchIdRef.current);
    watchIdRef.current = watchPosition(
      (pos) => {
        const map = mapInstanceRef.current;
        if (!map) return;
        const lat = pos.coords.latitude, lng = pos.coords.longitude;
        if (userMarkerRef.current) userMarkerRef.current.setLngLat([lng, lat]);
        const src = map.getSource('user-accuracy');
        if (src) src.setData({ type: 'FeatureCollection', features: [metersCirclePolygon(lat, lng, pos.coords.accuracy || 50)] });
      },
      () => {},
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 10000 },
    );
    return () => { if (watchIdRef.current !== null) clearWatch(watchIdRef.current); };
  }, [mapReady, followUser, locationAllowed]);

  // ---------- venue markers ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map) return;

    const ml = mapLibreRef.current;
    if (!ml) return;
    venuesRef.current = venues;

    // Clear previous markers
    markersRef.current.forEach(({ marker }) => marker.remove());
    markersRef.current = [];

    const heatFeatures = [];
    venues.forEach(v => {
      const loc = v.location;
      if (!loc?.latitude || !loc?.longitude) return;
      const shown = venueMatchesCategory(v, filterCategoryRef.current);

      // Heatmap point — weighted by crowd score (0-100 → 0-1)
      if (shown && typeof v.crowd === 'number') {
        heatFeatures.push({
          type: 'Feature',
          geometry: { type: 'Point', coordinates: [loc.longitude, loc.latitude] },
          properties: { weight: v.crowd / 100 },
        });
      }

      const isActive = activeVenue?.id === v.id;
      const el = buildMarkerEl(v, isActive);
      if (ownerPlaceId && v.place_id === ownerPlaceId) {
        // The dashboard map marks the owner's own pin with a permanent chip
        // so they can spot themselves without zooming to the label tier.
        el.style.zIndex = '2';
        const chip = document.createElement('div');
        chip.className = 'mlb-owner-chip';
        chip.textContent = 'Your venue';
        chip.style.background = mapIsDark ? '#f1ede0' : '#1e293b';
        chip.style.color = mapIsDark ? '#1e293b' : '#f1ede0';
        el.appendChild(chip);
      }
      el.addEventListener('click', (e) => {
        e.stopPropagation();
        setActiveVenue(v);
        mapEase(map, { center: [loc.longitude, loc.latitude], zoom: Math.max(map.getZoom(), 15), duration: 600 });
      });
      const anchor = (photoCacheRef.current[v.place_id] || v.photo_url) ? 'center' : 'bottom';
      if (!shown) el.style.display = 'none';
      const marker = new ml.Marker({ element: el, anchor }).setLngLat([loc.longitude, loc.latitude]).addTo(map);
      markersRef.current.push({ marker, el, venue: v });
    });
    setFilterHidesAll(venues.length > 0 && markersRef.current.every(({ el }) => el.style.display === 'none'));

    // Push heat data to the source
    const heatSrc = map.getSource('venue-heat');
    if (heatSrc) heatSrc.setData({ type: 'FeatureCollection', features: heatFeatures });

    // Space out any pins that landed on top of each other (zoomend re-runs this).
    declutterMarkers(map, markersRef.current);

    /* FRAME THE RESULTS. The map opened centred on the user at a fixed zoom,
       so a search could return 20 venues and show none of them: the chip said
       "All 20 results" over what looked like an empty map. Fit the viewport to
       the pins whenever the RESULT SET changes (not on every render, or a
       pan would snap back under the user's finger). maxZoom keeps a single
       result from diving to street level. */
    const key = venues.map(v => v.place_id || v.id).join(',');
    if (key === fittedKeyRef.current) return;
    fittedKeyRef.current = key;

    const points = venues
      .filter(v => v.location?.latitude && v.location?.longitude)
      .map(v => [v.location.longitude, v.location.latitude]);
    if (points.length === 0) return;

    /* Places sometimes returns one result on the other side of the country
       (a search around Bethlehem PA came back with a shop in California).
       Fitting to the raw extent then zooms out to the whole continent, which
       is a worse empty map than the one this is fixing. So fit to the CLUSTER:
       take the median point and drop anything absurdly far from it. The
       outlier keeps its pin and its place in the list; it just does not get
       to decide the viewport. */
    const sortedLng = points.map(p => p[0]).slice().sort((a, b) => a - b);
    const sortedLat = points.map(p => p[1]).slice().sort((a, b) => a - b);
    const midLng = sortedLng[sortedLng.length >> 1];
    const midLat = sortedLat[sortedLat.length >> 1];
    const kmFromMid = ([lng, lat]) => Math.hypot(
      (lng - midLng) * 111 * Math.cos(midLat * Math.PI / 180),
      (lat - midLat) * 111,
    );
    const sortedDist = points.map(kmFromMid).sort((a, b) => a - b);
    const medianDist = sortedDist[sortedDist.length >> 1] || 0;
    const limitKm = Math.max(15, medianDist * 4);
    let core = points.filter(p => kmFromMid(p) <= limitKm);
    if (core.length < 2) core = points;

    const bounds = core.reduce(
      (b, p) => b.extend(p),
      new ml.LngLatBounds(core[0], core[0]),
    );
    try {
      map.fitBounds(bounds, {
        padding: { top: 90, bottom: 190, left: 40, right: 40 }, // search bar above, venue cards below
        maxZoom: 15,
        duration: 600,
      });
    } catch { /* container not measured yet — the next result set re-fits */ }
  }, [venues, mapReady, buildMarkerEl, ownerPlaceId]); // eslint-disable-line react-hooks/exhaustive-deps

  // ---------- active venue highlight (only resize the 2 changed markers) ----------
  useEffect(() => {
    const prevId = prevActiveRef.current;
    const newId = activeVenue?.id;
    if (prevId === newId) return;
    prevActiveRef.current = newId;
    markersRef.current.forEach(({ el, venue }) => {
      if (venue.id !== prevId && venue.id !== newId) return;
      const isActive = venue.id === newId;
      const size = isActive ? 54 : 44;
      const inner = el.querySelector('.mlb-marker-inner') || el;
      inner.style.width = size + 'px';
      inner.style.height = size + 'px';
      // Tiny z-index range — the venue card overlay must always sit above markers.
      // (Active = 3, top rated = 2, normal = 1.)
      el.style.zIndex = isActive ? '3' : (venue.topRated ? '2' : '1');
      const svgEl = inner.querySelector('svg');
      if (svgEl) {
        svgEl.setAttribute('width', size);
        svgEl.setAttribute('height', Math.round(size * 1.32));
      } else if (photoCacheRef.current[venue.place_id] && isActive && venue.photo_url) {
        buildPhotoPin(venue.photo_url, true).then(dataUrl => {
          if (dataUrl) {
            photoCacheRef.current[venue.place_id] = dataUrl;
            inner.style.backgroundImage = `url("${dataUrl}")`;
          }
        });
      }
    });
  }, [activeVenue, buildPhotoPin]);

  // ---------- category filter (toggle visibility) ----------
  useEffect(() => {
    filterCategoryRef.current = filterCategory;
    applyCategoryFilter(mapInstanceRef.current, markersRef.current, filterCategory, setFilterHidesAll);
  }, [filterCategory]);

  // ---------- external imperative API ----------
  useEffect(() => {
    const map = mapInstanceRef.current;

    window.__flockOpenVenue = (placeId) => {
      const v = venues.find(venue => venue.place_id === placeId);
      if (v) openVenueDetail(placeId, { name: v.name, formatted_address: v.addr, place_id: placeId, rating: v.stars, photo_url: v.photo_url });
    };

    window.__flockPanToVenue = (target) => {
      if (!map) return;
      const placeId = typeof target === 'string' ? target : target?.place_id;
      const fLat = typeof target === 'object' ? parseFloat(target?.lat) : NaN;
      const fLng = typeof target === 'object' ? parseFloat(target?.lng) : NaN;

      const entry = placeId ? markersRef.current.find(e => e.venue.place_id === placeId) : null;
      if (entry) {
        const loc = entry.venue.location;
        mapEase(map, { center: [loc.longitude, loc.latitude], zoom: 17, duration: 700 });
        setActiveVenue(entry.venue);
        // Bounce — animate the INNER div's top offset (outer transform is MapLibre's)
        const inner = entry.el.querySelector('.mlb-marker-inner');
        if (inner) {
          inner.style.transition = 'top 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
          inner.style.position = 'relative';
          inner.style.top = '-12px';
          setTimeout(() => { inner.style.top = '0px'; }, 250);
          setTimeout(() => { inner.style.transition = 'width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease'; inner.style.position = ''; inner.style.top = ''; }, 700);
        }
      } else if (!isNaN(fLat) && !isNaN(fLng)) {
        mapEase(map, { center: [fLng, fLat], zoom: 17, duration: 700 });
        const nearby = markersRef.current.find(e => {
          const loc = e.venue.location;
          if (!loc) return false;
          const d = Math.sqrt(Math.pow(loc.latitude - fLat, 2) + Math.pow(loc.longitude - fLng, 2)) * 111000;
          return d < 100;
        });
        if (nearby) {
          setActiveVenue(nearby.venue);
        } else {
          // Drop a temp pin
          const venueName = target?.name || 'Venue';
          const venueAddr = target?.address || '';
          // A rating only exists if Google gave us one. It used to default to
          // 4.0, which renders next to a star as if it were measured.
          const venueRating = target?.rating ? parseFloat(target.rating) : null;
          const venuePhoto = target?.photo_url || null;
          // Crowd, price and "best time" were all derived from the first
          // character of the venue name plus its latitude. That is the third
          // instance of the invented-number pattern in this file; the other two
          // carry comments saying so. Nothing here is measured, so nothing here
          // gets a number. The real score arrives with the crowd fetch.
          const tempVenue = {
            id: 'temp_nav_' + Date.now(),
            place_id: placeId || null,
            name: venueName,
            addr: venueAddr,
            type: target?.types?.[0] ? target.types[0].replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()) : 'Place',
            category: (() => { const tt = (target?.types || []).join(' ').toLowerCase(); if (tt.includes('bar') || tt.includes('night_club')) return 'Nightlife'; if (tt.includes('restaurant') || tt.includes('cafe') || tt.includes('food') || tt.includes('diner') || tt.includes('juice')) return 'Food'; return 'Food'; })(),
            price: null,
            stars: venueRating,
            crowd: null,
            topRated: false,
            photo_url: venuePhoto,
            location: { latitude: fLat, longitude: fLng },
            types: [],
          };
          const ml = mapLibreRef.current;
          if (ml) {
            const el = buildMarkerEl(tempVenue, true);
            el.addEventListener('click', (e) => { e.stopPropagation(); setActiveVenue(tempVenue); mapEase(map, { center: [fLng, fLat], zoom: 17 }); });
            const anchor = venuePhoto ? 'center' : 'bottom';
            const marker = new ml.Marker({ element: el, anchor }).setLngLat([fLng, fLat]).addTo(map);
            markersRef.current.push({ marker, el, venue: tempVenue });
          }
          setActiveVenue(tempVenue);
          if (placeId) openVenueDetail(placeId, { name: venueName, formatted_address: venueAddr, place_id: placeId, rating: venueRating, photo_url: venuePhoto });
        }
      }
    };

    window.__flockGoToMyLocation = () => {
      if (!map) return;
      if (userMarkerRef.current) {
        const ll = userMarkerRef.current.getLngLat();
        mapEase(map, { center: [ll.lng, ll.lat], zoom: 15, duration: 600 });
        // Pulse the dot — box-shadow on the inner div only (transform is owned by MapLibre on the outer)
        if (userElRef.current) {
          userElRef.current.style.boxShadow = '0 0 0 12px rgba(59,130,246,0.35)';
          setTimeout(() => {
            if (userElRef.current) userElRef.current.style.boxShadow = '0 0 0 3px rgba(59,130,246,0.25)';
          }, 500);
        }
        return;
      }
      const center = map.getCenter();
      if (center) mapEase(map, { center: [center.lng, center.lat], zoom: 15 });
    };

    return () => { delete window.__flockOpenVenue; delete window.__flockPanToVenue; delete window.__flockGoToMyLocation; };
  }, [venues, openVenueDetail, setActiveVenue, buildMarkerEl]);

  // ---------- flock member live location markers ----------
  useEffect(() => {
    const map = mapInstanceRef.current;
    if (!mapReady || !map || !flockMemberLocations) return;
    const ml = mapLibreRef.current;
    if (!ml) return;
    const run = (mlMod) => {
      const currentIds = new Set(Object.keys(flockMemberLocations));
      // Remove gone
      Object.keys(memberMarkersRef.current).forEach(uid => {
        if (!currentIds.has(uid)) {
          memberMarkersRef.current[uid].marker.remove();
          delete memberMarkersRef.current[uid];
        }
      });
      Object.entries(flockMemberLocations).forEach(([uid, loc]) => {
        const lng = loc.lng, lat = loc.lat;
        const initial = escapeHtml((loc.name || '?')[0].toUpperCase());
        const dist = userLocation ? calcDistance(userLocation.lat, userLocation.lng, loc.lat, loc.lng) : '';
        const age = Math.round((Date.now() - loc.timestamp) / 1000);
        const ageStr = age < 10 ? 'just now' : age < 60 ? `${age}s ago` : `${Math.round(age / 60)}m ago`;
        const popupHtml = `<div style="font-family:'Hanken Grotesk',-apple-system,system-ui,sans-serif;display:flex;align-items:center;gap:10px;padding:6px 4px;min-width:160px">
          <div style="width:36px;height:36px;border-radius:18px;background:linear-gradient(135deg,#1e293b,#1a3a5c);display:flex;align-items:center;justify-content:center;flex-shrink:0">
            <span style="color:white;font-size:15px;font-weight:700">${initial}</span>
          </div>
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:700;color:#1e293b;margin:0 0 2px">${escapeHtml(loc.name)}</div>
            <div style="display:flex;align-items:center;gap:4px">
              <span style="width:6px;height:6px;border-radius:3px;background:#22c55e;display:inline-block"></span>
              <span style="font-size: 12px;color:#4b5563;font-weight:500">${dist ? dist + ' away · ' + ageStr : 'Live'}</span>
            </div>
          </div>
        </div>`;

        if (memberMarkersRef.current[uid]) {
          memberMarkersRef.current[uid].marker.setLngLat([lng, lat]);
          if (memberMarkersRef.current[uid].popup) memberMarkersRef.current[uid].popup.setHTML(popupHtml);
        } else {
          const el = document.createElement('div');
          el.style.width = '40px';
          el.style.height = '40px';
          el.style.cursor = 'pointer';
          el.innerHTML = `<svg aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 40 40">
            <circle cx="20" cy="20" r="18" fill="#1e293b" stroke="white" stroke-width="3"/>
            <circle cx="20" cy="20" r="18" fill="none" stroke="#22c55e" stroke-width="2" stroke-dasharray="4 4" opacity="0.6"/>
            <text x="20" y="26" text-anchor="middle" fill="white" font-size="16" font-weight="bold" font-family="Hanken Grotesk,sans-serif">${initial}</text>
          </svg>`;
          const popup = new mlMod.Popup({ offset: 25, closeButton: false }).setHTML(popupHtml);
          const marker = new mlMod.Marker({ element: el, anchor: 'center' }).setLngLat([lng, lat]).setPopup(popup).addTo(map);
          memberMarkersRef.current[uid] = { marker, popup };
        }
      });
    };
    run(ml);
  }, [mapReady, flockMemberLocations, userLocation, calcDistance]);

  // ---------- render ----------
  return (
    <div ref={mapRootRef} style={{ position: 'absolute', inset: 0 }}>
      {mapReady && filterHidesAll && filterCategory && filterCategory !== 'All' && (
        <p role="status" style={{ position: 'absolute', top: '10px', left: '50%', transform: 'translateX(-50%)', zIndex: 20, margin: 0, padding: '8px 12px', borderRadius: '10px', backgroundColor: 'var(--bg-card-solid)', border: '1px solid var(--border-default)', color: 'var(--text-secondary)', fontSize: 'var(--t-meta)', whiteSpace: 'nowrap' }}>No {filterCategory.toLowerCase()} spots on this map. Pick another filter or move the map.</p>
      )}
      {!mapReady && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 10, backgroundColor: '#1a2a3a', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '12px' }}>
          <div style={{ width: '32px', height: '32px', border: '3px solid rgba(255,255,255,0.15)', borderTopColor: '#6d9ac3', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
          <p style={{ color: '#8ec3b9', fontSize: 'var(--t-label)', fontWeight: '500', margin: 0 }}>Loading map...</p>
        </div>
      )}
      <style>{`
        /* opacity 0.4 on top of grey-on-white put the legally-required credit
           well under 4.5:1. Full opacity; MapLibre's own colours are readable. */
        .maplibregl-ctrl-attrib { font-size: 12px !important; opacity: 1; }
        .maplibregl-ctrl-attrib a { color: #33475e; }
        .maplibregl-ctrl-logo { display: none !important; }
        .mlb-venue-marker { user-select: none; -webkit-user-select: none; }
        /* Markers must never bleed above overlay UI (venue cards, sheets, etc.) */
        .maplibregl-marker { z-index: 1; }
        .maplibregl-canvas-container { z-index: 0; }

        /* ---- Apple-Maps-style name label under each pin ---- */
        .mlb-marker-label {
          margin-top: 4px;
          padding: 3px 7px;
          border-radius: 8px;
          background: rgba(15,23,42,0.78);
          backdrop-filter: blur(8px);
          -webkit-backdrop-filter: blur(8px);
          color: #f1f5f9;
          font-family: 'Hanken Grotesk', system-ui, -apple-system, sans-serif;
          font-size: 12px;
          font-weight: 700;
          letter-spacing: -0.1px;
          line-height: 1.15;
          box-shadow: 0 2px 8px rgba(0,0,0,0.35), 0 0 0 1px rgba(255,255,255,0.06);
          opacity: 0;
          transform: translateY(-4px) scale(0.85);
          transition: opacity 0.18s ease, transform 0.18s ease;
          pointer-events: none;
          max-width: 180px;
          display: flex;
          align-items: center;
          gap: 5px;
        }
        .mlb-label-name {
          /* Allow up to 2 lines on long names; ellipsize if it still overflows. */
          display: -webkit-box;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;
          text-overflow: ellipsis;
          word-break: break-word;
        }
        .mlb-label-rating {
          color: #fbbf24;
          font-weight: 800;
          font-size: 12px;
          letter-spacing: 0;
          display: inline-flex;
          align-items: center;
          gap: 3px;
        }

        /* The owner's own pin on the dashboard map: a chip that is never
           zoom-gated, because spotting yourself should not require zooming.
           Colours are set inline (theme-inverted, same rule as the pins). */
        .mlb-owner-chip {
          margin-top: 3px;
          padding: 2px 8px;
          border-radius: 8px;
          font-family: 'Hanken Grotesk', system-ui, -apple-system, sans-serif;
          font-size: 11px;
          font-weight: 700;
          letter-spacing: -0.1px;
          white-space: nowrap;
          box-shadow: 0 2px 8px rgba(0,0,0,0.35);
          pointer-events: none;
        }

        /* Show labels only when zoomed in enough to read them. */
        [data-zoom-tier="hi"] .mlb-marker-label {
          opacity: 1;
          transform: translateY(0) scale(1);
        }

        /* Shrink markers when zoomed out so the map doesn't get blanketed. */
        [data-zoom-tier="lo"] .mlb-marker-inner {
          transform: scale(0.65);
          transform-origin: center center;
          transition: transform 0.18s ease, width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease;
        }
        [data-zoom-tier="mid"] .mlb-marker-inner,
        [data-zoom-tier="hi"] .mlb-marker-inner {
          transform: scale(1);
          transition: transform 0.18s ease, width 0.2s ease, height 0.2s ease, box-shadow 0.2s ease;
        }
      `}</style>
      <div ref={mapRef} style={{ width: '100%', height: '100%' }} />

      {/* My Location button. Hidden when the map is not following the
          viewer (venue dashboard): with no tracked position it could only
          ever re-center on nothing, and a button that cannot succeed does
          not render. */}
      {followUser && (
      <button aria-label="My Location" className="hit44"
        onClick={() => window.__flockGoToMyLocation && window.__flockGoToMyLocation()}
        style={{
          position: 'absolute', bottom: '80px', right: '12px',
          width: '44px', height: '44px', borderRadius: '22px',
          border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer',
          boxShadow: '0 2px 8px rgba(0,0,0,0.25)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          zIndex: 5, transition: 'transform 0.2s ease',
        }}
        onMouseEnter={(e) => { e.currentTarget.style.transform = 'scale(1.1)'; }}
        onMouseLeave={(e) => { e.currentTarget.style.transform = 'scale(1)'; }}
        title="My Location"
      >
        <svg aria-hidden="true" focusable="false" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <circle cx="12" cy="12" r="4"/><line x1="12" y1="2" x2="12" y2="6"/><line x1="12" y1="18" x2="12" y2="22"/><line x1="2" y1="12" x2="6" y2="12"/><line x1="18" y1="12" x2="22" y2="12"/>
        </svg>
      </button>
      )}

      {/* Zoom controls */}
      <div style={{
        position: 'absolute', bottom: '184px', right: '12px',
        display: 'flex', flexDirection: 'column',
        borderRadius: '22px', overflow: 'hidden',
        boxShadow: '0 2px 8px rgba(0,0,0,0.25)', zIndex: 5,
      }}>
        <button aria-label="Zoom in" className="hit44"
          onClick={() => mapInstanceRef.current && mapInstanceRef.current.zoomIn({ duration: 150 })}
          style={{ width: '44px', height: '40px', border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          title="Zoom in"
        >
          <svg aria-hidden="true" focusable="false" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2.5" strokeLinecap="round">
            <line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>
          </svg>
        </button>
        <div style={{ height: '1px', background: 'var(--border-default)' }} />
        <button aria-label="Zoom out" className="hit44"
          onClick={() => mapInstanceRef.current && mapInstanceRef.current.zoomOut({ duration: 150 })}
          style={{ width: '44px', height: '40px', border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          title="Zoom out"
        >
          <svg aria-hidden="true" focusable="false" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2.5" strokeLinecap="round">
            <line x1="5" y1="12" x2="19" y2="12"/>
          </svg>
        </button>
      </div>

      {/* Map / Satellite toggle. Hidden outright when there is no MapTiler key,
          because MapTiler hybrid is now the only satellite imagery Flock is
          licensed to draw — a button that swaps to nothing is worse than no
          button. Every shipping build sets the key, so this renders in all of
          them. */}
      {SATELLITE_AVAILABLE && (
      <button className="hit44"
        aria-label={mapType === 'roadmap' ? 'Switch to satellite view' : 'Switch to map view'}
        onClick={toggleMapType}
        style={{
          position: 'absolute', bottom: '132px', right: '12px',
          width: '44px', height: '44px', borderRadius: '22px',
          border: 'none', background: 'var(--bg-card-solid)', cursor: 'pointer',
          boxShadow: '0 2px 8px rgba(0,0,0,0.25)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          zIndex: 5, transition: 'transform 0.2s ease',
        }}
        onMouseEnter={(e) => { e.currentTarget.style.transform = 'scale(1.1)'; }}
        onMouseLeave={(e) => { e.currentTarget.style.transform = 'scale(1)'; }}
        title={mapType === 'roadmap' ? 'Switch to Satellite' : 'Switch to Map'}
      >
        {mapType === 'roadmap' ? (
          <svg aria-hidden="true" focusable="false" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <circle cx="12" cy="12" r="10"/><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"/><path d="M2 12h20"/>
          </svg>
        ) : (
          <svg aria-hidden="true" focusable="false" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6"/><line x1="8" y1="2" x2="8" y2="18"/><line x1="16" y1="6" x2="16" y2="22"/>
          </svg>
        )}
      </button>
      )}
    </div>
  );
});

// Brand Colors
// Base colors (light mode defaults — used outside components too)
const colorsLight = {
  navy: '#1e293b',
  navyBg: '#1e293b',
  navyLight: '#1a3a5c',
  navyMid: '#2d5a87',
  navyMidBg: '#2d5a87',
  skyBlue: '#4a7ba7',
  cream: '#f1ede0',
  creamDark: '#e8e0d5',
  steel: '#2d5a87',   // brand accent (renamed from 'teal' 2026-07 — the color IS steel navy; old name was a trap)
  amber: '#F59E0B',
  red: '#EF4444',
  food: '#F97316',
  nightlife: '#1a3a5c',
  music: '#2d5a87',
  sports: '#22C55E',
  // WCAG 1.4.3. Was #64748b (4.06:1 on paper, 3.64:1 on --bg-tertiary) and
  // #94a3b8 (2.19:1 / 1.96:1). Same hue, dropped in lightness until both clear
  // 4.5:1 on paper, white and --bg-tertiary.
  textSecondary: '#455263',
  textTertiary: '#586376',
  borderDefault: '#e5e7eb',
  bgHover: '#f3f4f6',
  bgTertiary: '#e8e0d5',
  disabled: '#e5e7eb',
  // WCAG 1.4.3, and the reason these are separate keys rather than a change to
  // `red`/`amber`/`food` above: those three are correct as FILL. A 6px status
  // dot, a chip background, a 1px border and a chart bar are non-text and read
  // fine at full saturation, and darkening them would mute the whole palette.
  // As TEXT on a light surface they do not clear the floor: #EF4444 measures
  // 3.76:1 on a white card and 3.21:1 on paper, #F59E0B measures 2.15 and 1.83,
  // #F97316 measures 2.80 and 2.39. Nearly every inline validation message in
  // the app is 12px `red`, which is the one string a person who is stuck most
  // needs to read. These are the same hues dropped in lightness until they
  // clear 4.5:1 on white, on paper and on --bg-tertiary.
  // Use *Text for anything a screen reader would read as words. Keep the plain
  // key for dots, fills, borders and bars.
  redText: '#b91c1c',    // 6.47 white / 5.52 paper
  amberText: '#92400e',  // 7.09 / 6.05 / 5.42 on --bg-tertiary
  foodText: '#9a3412',   // 7.31 / 6.24
};

const colorsDark = {
  navy: '#f1ede0',
  navyBg: '#1e3a5c',
  navyLight: '#94a3b8',
  navyMid: '#64748b',
  navyMidBg: '#2d5a87',
  skyBlue: '#38bdf8',
  cream: '#0f172a',
  creamDark: '#1e3a5c',
  steel: '#6d9ac3',   // brand accent (renamed from 'teal' 2026-07)
  amber: '#F59E0B',
  red: '#EF4444',
  food: '#F97316',
  nightlife: '#94a3b8',
  music: '#64748b',
  sports: '#22C55E',
  // Was #94a3b8 (4.51:1 on --bg-hover #1e3a5c, borderline) and #64748b
  // (3.75 / 3.07 / 2.43 — failed on every dark surface). Lightened in place.
  textSecondary: '#c2ccd9',
  textTertiary: '#a7b3c4',
  borderDefault: '#1e3a5c',
  bgHover: '#1e3a5c',
  bgTertiary: '#1e3a5c',
  disabled: '#2d5a87',
  // Dark mode fails in the other direction: the saturated hues are bright
  // enough on #0f172a but land on --bg-hover #1e3a5c too, where #EF4444 is
  // under 4:1. These match the --accent-*-text tokens index.css already
  // defines for dark, so a chip and a bare line of text agree.
  redText: '#fca5a5',    // 7.71 on a card / 6.10 on --bg-hover
  amberText: '#fbbf24',  // 10.69 / 8.76 / 6.93
  foodText: '#fb923c',   // 7.89 / 6.46 / 5.11
};

// Static fallback for outside-component usage (loading screen)
// eslint-disable-next-line no-unused-vars
const colors = colorsLight;

// The decorative phone bezel is a DESKTOP-ONLY preview shell. On the real device
// (Capacitor) or any phone-sized viewport it must not render — otherwise the app
// draws a fake phone border inside the actual phone. Native detection + width
// check; evaluated once (rotation/resize edge cases don't need live re-eval).
// VENUE PLAN PRICES. One copy, because there used to be three and they
// disagreed with the server.
//
// $99 is VENUE-PRICING.md's call (2026-08-20), which supersedes the $75 Pro
// price set on 2026-08-14, and it is already what the backend bills against:
// `VENUE_PRICE_USD = 99` in backend/routes/admin.js, which is the only place
// in the whole product that has ever held a venue price. There is no route a
// venue owner can call that returns it, so this is still a hardcode; it is one
// hardcode instead of three, it agrees with the server's, and both carry the
// same citation.
//
// Premium stays at $35 here on purpose. VENUE-PRICING.md §4 collapses the
// three tiers to two and retires Premium, but that move drops server-side
// gates (promotions, events, incoming-flocks) at the same time. Changing the
// cards without the gates would advertise features the backend still refuses,
// so the collapse is one commit that has to include backend/routes, and this
// is not it.
const VENUE_PLAN_PRICE = { premium: 35, pro: 99 };
const venuePlanPriceLabel = (tier, per = 'mo') =>
  VENUE_PLAN_PRICE[tier] ? `$${VENUE_PLAN_PRICE[tier]}/${per}` : null;

// The NFC check-in screen. Mounted (not called) by the screen slot, so its
// hooks live in a component of their own.
const NfcCheckinView = ({ placeId, sig, onViewVenue, onOpenApp }) => {
  const [status, setStatus] = useState('loading'); // 'loading' | 'ok' | 'error'
  const [checkedInAt, setCheckedInAt] = useState(null);
  const [venueName, setVenueName] = useState(null);
  const [failure, setFailure] = useState(null); // { status, message, offline }
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    if (!placeId) { setStatus('error'); setFailure({ status: 400, message: 'This link has no venue on it.' }); return undefined; }
    let cancelled = false;
    setStatus('loading');
    setFailure(null);
    getNfcCheckin(placeId, sig)
      .then((res) => {
        if (cancelled) return;
        setCheckedInAt(res?.checked_in_at || new Date().toISOString());
        setVenueName(res?.venue_name || null);
        setStatus('ok');
      })
      .catch((err) => {
        if (cancelled) return;
        // Keep what the server said. One screen used to cover every failure
        // with "Try tapping the tag again", which is wrong advice for an
        // unknown tag (404) and a rate limit (429), and the only action left
        // for the website.
        setFailure({
          status: err?.status || 0,
          message: err?.message || '',
          offline: !!(err?.isOffline || err?.isNetworkError || err?.isTimeout),
        });
        setStatus('error');
      });
    return () => { cancelled = true; };
  }, [placeId, sig, attempt]);

  const failureText = (() => {
    if (!failure) return 'Check-in failed.';
    if (failure.offline) return "You're offline. Tap the tag again when you have signal.";
    if (failure.status === 404) return 'This tag is not on Flock\u2019s map. Tell the venue.';
    if (failure.status === 429) return failure.message || 'Too many check-ins. Try again later.';
    return failure.message || 'Check-in failed. Try tapping the tag again.';
  })();
  const canRetry = !failure || failure.offline || failure.status === 0 || failure.status >= 500;

  const btn = { padding: '14px 32px', borderRadius: '14px', border: 'none', background: '#1e293b', color: 'white', fontWeight: '600', fontSize: 'var(--t-body)', cursor: 'pointer' };
  const ghost = { padding: '12px 28px', background: 'none', border: 'none', color: 'rgba(241,237,224,0.7)', fontSize: 'var(--t-label)', fontWeight: '600', cursor: 'pointer' };

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 100,
      backgroundColor: '#0f172a',
      display: 'flex', flexDirection: 'column',
      alignItems: 'center', justifyContent: 'center',
      padding: '32px 24px', textAlign: 'center',
      color: '#f1ede0', fontFamily: "'Hanken Grotesk', system-ui, -apple-system, sans-serif",
    }}>
      <div style={{ marginBottom: '32px' }}>
        <div style={{ fontSize: 'var(--t-display)', fontWeight: '600', letterSpacing: '-1px', color: '#f1ede0' }}>Flock</div>
      </div>

      {status === 'loading' && (
        <div role="status" aria-label="Checking you in" style={{ width: '32px', height: '32px', border: '3px solid rgba(255,255,255,0.15)', borderTopColor: '#6d9ac3', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
      )}

      {status === 'ok' && (
        <>
          <div style={{ width: '64px', height: '64px', borderRadius: '50%', backgroundColor: 'rgba(16,185,129,0.18)', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '20px' }}>
            <span style={{ fontSize: 'var(--t-display)', color: '#10b981', lineHeight: 1 }}>{'\u2713'}</span>
          </div>
          <h1 style={{ fontSize: 'var(--t-display)', fontWeight: '600', margin: '0 0 8px', color: '#f1ede0', letterSpacing: '-0.4px' }}>You're checked in{venueName ? ` at ${venueName}` : ''}</h1>
          <p style={{ fontSize: 'var(--t-label)', color: 'rgba(241,237,224,0.6)', margin: '0 0 28px' }}>{new Date(checkedInAt).toLocaleString([], { weekday: 'short', hour: 'numeric', minute: '2-digit' })}</p>
          <button className="hit44" onClick={() => onViewVenue(placeId)} style={btn}>View venue in Flock</button>
        </>
      )}

      {status === 'error' && (
        <>
          <h1 style={{ fontSize: 'var(--t-display)', fontWeight: '600', margin: '0 0 8px', color: '#f1ede0' }}>Not checked in</h1>
          <p role="alert" style={{ fontSize: 'var(--t-label)', color: 'rgba(241,237,224,0.6)', margin: '0 0 24px', maxWidth: '320px', lineHeight: 1.5 }}>{failureText}</p>
          {canRetry && <button className="hit44" onClick={() => setAttempt(n => n + 1)} style={btn}>Try again</button>}
          <button className="hit44" onClick={onOpenApp} style={{ ...ghost, marginTop: canRetry ? '8px' : 0 }}>Open Flock</button>
        </>
      )}
    </div>
  );
};

const isFullBleedNow = () => (typeof window !== 'undefined') && (
  (window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()) ||
  (window.matchMedia && window.matchMedia('(max-width: 500px)').matches)
);
